import { useCallback, useEffect, useMemo, useState, type FormEvent } from 'react'
import { CleanupDialog } from './CleanupDialog'
import { cleanupCounts } from './cleanup'
import { ConfirmDialog } from '@anima/player-ui'
import { useI18n } from '../../i18n/I18nProvider'
import { apiDelete, apiGet, apiPatch, apiPost } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { loadCharacters, loadLocations, type CharacterRef, type LocationRef } from '../../lib/refs'
import { clockSettings, formatGameTime, useClockSettings } from '../../lib/clockFormat'

/**
 * Game-Admin "Intents" tab — the unified plans and tasks store
 * (plan-intents-unified.md). Replaces the legacy assignments panel:
 * human-set tasks and character-owned intents live in one place. Admins
 * create, edit (PATCH), complete and delete here; characters create their own
 * via [INTENT:] markers and retrospect goals.
 */

interface Intent {
  id: string
  source: 'human' | 'character'
  owner: string
  participants: Record<string, { role?: string; progress?: unknown[] }>
  title: string
  description: string
  trigger: { kind?: string; location_id?: string; run_date?: string; repeat?: 'daily'; at?: string }
  target_count?: number
  priority: number
  status: string
  location_id?: string
  outfit_hint?: string
  created_at?: string
  expires_at?: string
  action?: { type?: string; destination?: { location_id: string; room_id?: string }; scope?: 'pair' | 'party'; after_arrival?: { type: 'pair'; pose_key: string } }
  meta?: { progress_type?: string; repeat_state?: { day: string; log: Array<{ day: string; result: 'done' | 'missed'; count: number }> }; expired_reason?: string; travel?: { phase?: string; reason?: string; expected_members?: string[]; destination_label?: string } }
}

type TriggerKind = 'standing' | 'now' | 'at_location' | 'at_time'

interface FormState {
  title: string
  description: string
  owner: string
  participants: string[] // additional participants beyond the owner
  priority: number
  triggerKind: TriggerKind
  repeat: '' | 'daily'
  dailyAt: string
  targetCount: number
  progressType: string
  locationId: string
  runDate: string // the stored GAME stamp of an edited at_time intent ('' on create)
  runInMin: number // at_time: game minutes from now; 0 = keep runDate (edit only)
  outfitHint: string
  durationMin: number // 0 = never expires
  actionKind: 'plan' | 'travel_together'
  destinationId: string
  destinationRoomId: string
  scope: 'pair' | 'party'
  afterArrivalKey: string
}

const INITIAL_FORM: FormState = {
  title: '',
  description: '',
  owner: '',
  participants: [],
  priority: 3,
  triggerKind: 'standing',
  repeat: '',
  dailyAt: '09:00',
  targetCount: 0,
  progressType: '',
  locationId: '',
  runDate: '',
  runInMin: 0,
  outfitHint: '',
  durationMin: 0,
  actionKind: 'plan',
  destinationId: '',
  destinationRoomId: '',
  scope: 'pair',
  afterArrivalKey: '',
}

const DURATION_OPTIONS: Array<{ value: number; label: string }> = [
  { value: 0, label: 'Never expires' },
  { value: 60, label: '1 hour' },
  { value: 360, label: '6 hours' },
  { value: 1440, label: '1 day' },
  { value: 2880, label: '2 days' },
  { value: 10080, label: '7 days' },
]

// "Starts in" for an at_time intent — GAME minutes from now. The browser has
// no game clock, so it never computes a stamp itself: the server turns
// run_in_minutes into the canonical run_date (like duration_minutes).
const RUN_IN_OPTIONS = DURATION_OPTIONS.filter((d) => d.value > 0)

/** A canonical GAME stamp ("Y0002-D109T14:23:45") → "Y0002-D109 14:23", the
 *  clock part in the configured format. These are world-calendar stamps, not
 *  system time: no `Date` is involved and there is no timezone to apply. */
function gameStampLabel(stamp: string | undefined): string {
  const m = /^(.*)T(\d{2}):(\d{2})/.exec(stamp || '')
  if (!m) return (stamp || '').slice(0, 16).replace('T', ' ')
  return `${m[1]} ${formatGameTime(parseInt(m[2], 10), parseInt(m[3], 10), clockSettings().format)}`
}

function expiresAtLabel(iso: string | undefined): string {
  return gameStampLabel(iso)
}

const PRIORITY_LABELS: Record<number, string> = {
  1: 'Critical',
  2: 'High',
  3: 'Normal',
  4: 'Low',
  5: 'Idle',
}

const EXPIRY_REASON_LABELS: Record<string, string> = {
  cap: 'limit reached',
  deadline: 'deadline passed',
  replaced: 'replaced by reflection',
  duplicate: 'duplicate merged',
  cleanup: 'ended by clean-up',
  participant_gone: 'a participant left the world',
}

const TRIP_PHASE_LABELS: Record<string, string> = {
  waiting_consent: 'Waiting for consent',
  ready: 'Ready to travel',
  starting: 'Starting',
  travelling: 'Travelling',
  blocked: 'Blocked',
  arrived: 'Arrived',
  waiting_activity: 'Waiting for activity consent',
  activity: 'Activity in progress',
  completed: 'Completed',
  cancelled: 'Cancelled',
}

const POLL_INTERVAL_MS = 15_000

function triggerSummary(it: Intent, locName: (id: string) => string, t: (s: string) => string): string {
  if (it.trigger?.repeat === 'daily') return `↻ ${t('daily')}${it.trigger.kind === 'at_time' ? ` ${it.trigger.at}` : ''}`
  const k = it.trigger?.kind || 'standing'
  if (k === 'at_location') return `@ ${locName(it.trigger?.location_id || it.location_id || '')}`
  if (k === 'at_time') return `⏰ ${gameStampLabel(it.trigger?.run_date)}`
  if (k === 'now') return t('now')
  return t('standing')
}

const SORT_COLUMNS = ['title', 'owner', 'source', 'trigger', 'priority', 'expires', 'progress', 'status', 'created'] as const
type SortColumn = typeof SORT_COLUMNS[number]
const STATUSES = ['active', 'done', 'expired', 'cancelled', 'all'] as const
const TRIGGERS = ['standing', 'now', 'at_location', 'at_time', 'daily'] as const
interface IntentView {
  character: string
  status: typeof STATUSES[number]
  source: '' | 'human' | 'character'
  trigger: string
  search: string
  sort: { column: SortColumn; direction: 'asc' | 'desc' } | null
}
const DEFAULT_VIEW: IntentView = { character: '', status: 'active', source: '', trigger: '', search: '', sort: null }
const VIEW_KEY = 'ga.intents.view'

function loadIntentView(): IntentView {
  try {
    const raw = window.localStorage.getItem(VIEW_KEY)
    if (!raw) return DEFAULT_VIEW
    const p = JSON.parse(raw)
    return {
      character: typeof p.character === 'string' ? p.character : '',
      status: STATUSES.includes(p.status) ? p.status : 'active',
      source: ['human', 'character'].includes(p.source) ? p.source : '',
      trigger: TRIGGERS.includes(p.trigger) ? p.trigger : '',
      search: typeof p.search === 'string' ? p.search : '',
      sort: p.sort && SORT_COLUMNS.includes(p.sort.column) && ['asc', 'desc'].includes(p.sort.direction)
        ? { column: p.sort.column, direction: p.sort.direction } : null,
    }
  } catch { return DEFAULT_VIEW }
}

function saveIntentView(view: IntentView): void {
  try {
    window.localStorage.setItem(VIEW_KEY, JSON.stringify(view))
  } catch { /* Filtering still works when browser storage is unavailable. */ }
}

function intentOwner(it: Intent): string {
  return it.owner || Object.keys(it.participants || {})[0] || '—'
}

function triggerBucket(it: Intent): string {
  return it.trigger?.repeat === 'daily' ? 'daily' : it.trigger?.kind || 'standing'
}

function intentProgress(it: Intent): number {
  return Math.max(0, ...Object.values(it.participants || {}).map((p) => p.progress?.length || 0))
}

function compareString(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0
}

function compareIntents(a: Intent, b: Intent, sort: IntentView['sort'], locName: (id: string) => string): number {
  const fallback = () => a.priority - b.priority || compareString(b.created_at || '', a.created_at || '') || compareString(a.id, b.id)
  if (!sort) return fallback()
  let result = 0
  switch (sort.column) {
    case 'title': result = a.title.localeCompare(b.title, undefined, { sensitivity: 'base' }); break
    case 'owner': result = intentOwner(a).localeCompare(intentOwner(b), undefined, { sensitivity: 'base' }); break
    case 'source': result = compareString(a.source, b.source); break
    case 'status': result = compareString(a.status, b.status); break
    case 'priority': result = a.priority - b.priority; break
    case 'created': result = compareString(a.created_at || '', b.created_at || ''); break
    case 'expires':
      if (!!a.expires_at !== !!b.expires_at) return a.expires_at ? -1 : 1
      result = compareString(a.expires_at || '', b.expires_at || '')
      break
    case 'progress':
      if ((!!a.target_count && a.target_count > 0) !== (!!b.target_count && b.target_count > 0)) return (a.target_count || 0) > 0 ? -1 : 1
      result = (a.target_count ? intentProgress(a) / a.target_count : 0) - (b.target_count ? intentProgress(b) / b.target_count : 0)
      break
    case 'trigger': {
      const ak = triggerBucket(a), bk = triggerBucket(b)
      result = TRIGGERS.indexOf(ak as typeof TRIGGERS[number]) - TRIGGERS.indexOf(bk as typeof TRIGGERS[number])
      if (!result && ak === 'at_time') result = compareString(a.trigger?.run_date || '', b.trigger?.run_date || '')
      if (!result && ak === 'at_location') result = locName(a.trigger?.location_id || a.location_id || '').localeCompare(locName(b.trigger?.location_id || b.location_id || ''))
      break
    }
  }
  return (sort.direction === 'asc' ? result : -result) || fallback()
}

export function IntentsTab() {
  // Subscribe to the shared clock settings so the stamps above re-render
  // once the server-configured format arrives.
  useClockSettings()
  const { t } = useI18n()
  const { toast } = useToast()
  const [intents, setIntents] = useState<Intent[] | null>(null)
  const [characters, setCharacters] = useState<CharacterRef[]>([])
  const [locations, setLocations] = useState<LocationRef[]>([])
  const [progressTypes, setProgressTypes] = useState<string[]>([])
  const [actionTypes, setActionTypes] = useState<string[]>([])
  const [sharedActivityOptions, setSharedActivityOptions] = useState<string[]>([])
  const [view, setView] = useState<IntentView>(loadIntentView)
  useEffect(() => { saveIntentView(view) }, [view])
  const [cleanupOpen, setCleanupOpen] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [form, setForm] = useState<FormState>(INITIAL_FORM)
  const [submitting, setSubmitting] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  // original participant objects of the intent being edited — preserved so an
  // admin edit does not wipe role/progress of participants that stay.
  const [editParticipants, setEditParticipants] = useState<
    Record<string, { role?: string; progress?: unknown[] }>
  >({})

  const locName = useCallback(
    (id: string) => locations.find((l) => l.id === id)?.name || id || '—',
    [locations],
  )

  const characterNames = useMemo(() => [...new Set([
    ...(intents || []).flatMap((it) => [it.owner, ...Object.keys(it.participants || {})]),
    view.character,
  ].filter(Boolean))].sort((a, b) => a.localeCompare(b)), [intents, view.character])

  const visibleIntents = useMemo(() => (intents || []).filter((it) => {
    const names = [it.owner, ...Object.keys(it.participants || {})]
    return (!view.character || names.some((name) => name?.toLowerCase() === view.character.toLowerCase()))
      && (view.status === 'all' || it.status === view.status)
      && (!view.source || it.source === view.source)
      && (!view.trigger || triggerBucket(it) === view.trigger)
      && `${it.title || ''} ${it.description || ''}`.toLowerCase().includes(view.search.toLowerCase())
  }).sort((a, b) => compareIntents(a, b, view.sort, locName)), [intents, view, locName])

  const sortHeader = (column: SortColumn, label: string) => (
    <th aria-sort={view.sort?.column === column ? (view.sort.direction === 'asc' ? 'ascending' : 'descending') : 'none'}>
      <button type="button" style={{ background: 'none', border: 0, padding: 0, color: 'inherit', font: 'inherit', cursor: 'pointer' }}
        onClick={() => setView((v) => ({ ...v, sort: { column, direction: v.sort?.column === column && v.sort.direction === 'asc' ? 'desc' : 'asc' } }))}>
        {t(label)}{view.sort?.column === column ? (view.sort.direction === 'asc' ? ' ▲' : ' ▼') : ''}
      </button>
    </th>
  )

  const reload = useCallback(async () => {
    try {
      const data = await apiGet<Intent[]>(`/intents${view.status === 'active' ? '?status=active' : ''}`)
      setIntents(data || [])
      setError(null)
    } catch (e) {
      setError((e as Error).message)
    }
  }, [view.status])

  useEffect(() => {
    loadCharacters().then(setCharacters).catch(() => setCharacters([]))
    loadLocations().then(setLocations).catch(() => setLocations([]))
    apiGet<string[]>('/intents/progress-types').then(setProgressTypes)
      .catch((e) => setError((e as Error).message))
    apiGet<string[]>('/intents/action-types').then(setActionTypes)
      .catch((e) => setError((e as Error).message))
    apiGet<string[]>('/intents/shared-activity-options').then(setSharedActivityOptions)
      .catch((e) => {
        setSharedActivityOptions([])
        setError((e as Error).message)
      })
  }, [])

  useEffect(() => {
    reload()
    const id = window.setInterval(reload, POLL_INTERVAL_MS)
    return () => window.clearInterval(id)
  }, [reload])

  const resetForm = useCallback(() => {
    setEditingId(null)
    setEditParticipants({})
    setForm(INITIAL_FORM)
  }, [])

  const handleEdit = useCallback(
    (it: Intent) => {
      const allParts = Object.keys(it.participants || {})
      const owner = it.owner || allParts[0] || ''
      const extras = allParts.filter((p) => p !== owner)
      const k = (it.trigger?.kind as TriggerKind) || 'standing'
      setEditParticipants(it.participants || {})
      setForm({
        title: it.title || '',
        description: it.description || '',
        owner,
        participants: extras,
        priority: it.priority || 3,
        triggerKind: ['standing', 'now', 'at_location', 'at_time'].includes(k) ? k : 'standing',
        locationId: it.trigger?.location_id || it.location_id || '',
        runDate: it.trigger?.run_date || '',
        runInMin: 0,
        repeat: it.trigger?.repeat || '',
        dailyAt: it.trigger?.at || '09:00',
        targetCount: it.target_count || 0,
        progressType: it.meta?.progress_type || '',
        outfitHint: it.outfit_hint || '',
        // expires_at is absolute; we cannot reverse it to a preset, so keep the
        // existing expiry untouched on edit unless the admin picks a new duration.
        durationMin: 0,
        actionKind: 'plan',
        destinationId: '',
        destinationRoomId: '',
        scope: 'pair',
        afterArrivalKey: '',
      })
      setEditingId(it.id)
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' })
    },
    [],
  )

  const handleSubmit = useCallback(
    async (e: FormEvent) => {
      e.preventDefault()
      if (!form.title.trim()) {
        toast(t('Title is required'), 'error')
        return
      }
      if (!form.owner.trim()) {
        toast(t('Pick an owner'), 'error')
        return
      }
      if (form.actionKind === 'travel_together' && (!form.destinationId || form.participants.length !== 1)) {
        toast(t('Pick a destination and exactly one companion'), 'error')
        return
      }
      const trigger: Record<string, unknown> = { kind: form.triggerKind }
      if (form.triggerKind === 'at_location') {
        if (!form.locationId) {
          toast(t('Pick a location'), 'error')
          return
        }
        trigger.location_id = form.locationId
      }
      if (form.repeat) trigger.repeat = form.repeat
      if (form.triggerKind === 'at_time') {
        if (form.repeat === 'daily') {
          trigger.at = form.dailyAt
        } else if (form.runInMin > 0) {
          trigger.run_in_minutes = form.runInMin
        } else if (editingId && form.runDate) {
          trigger.run_date = form.runDate
        } else {
          toast(t('Pick when it starts'), 'error')
          return
        }
      }
      // Build participants dict (owner + extras), preserving role/progress of
      // members that already existed on the edited intent.
      const names = [form.owner.trim(), ...form.participants].filter(
        (n, i, arr) => n && arr.indexOf(n) === i,
      )
      const participants: Record<string, { role?: string; progress?: unknown[] }> = {}
      for (const n of names) {
        participants[n] = form.actionKind === 'travel_together'
          ? { role: n === form.owner.trim() ? 'leader' : 'follower', progress: [] }
          : editParticipants[n] || { role: '', progress: [] }
      }
      const payload: Record<string, unknown> = {
        title: form.title.trim(),
        description: form.description.trim(),
        owner: form.owner.trim(),
        participants,
        priority: form.priority,
        trigger,
        location_id: form.triggerKind === 'at_location' ? form.locationId : '',
        outfit_hint: form.outfitHint.trim(),
      }
      // Count and progress type belong to ordinary plans only — an executable
      // action's own validator owns every other field of its intent.
      if (form.actionKind === 'plan') {
        payload.target_count = form.targetCount
        payload.meta = { progress_type: form.progressType }
      }
      // Only stamp source on create — editing must not flip a character-owned
      // intent into a human one.
      if (!editingId) payload.source = 'human'
      // Expiry: only set when a duration preset is chosen. 0 = leave as-is on
      // edit / "never" on create. GAME minutes — the server computes the stamp.
      if (!form.repeat && form.durationMin > 0) {
        payload.duration_minutes = form.durationMin
      } else if (!editingId) {
        payload.expires_at = ''
      }
      if (!editingId && form.actionKind === 'travel_together') {
        payload.action = {
          type: 'travel_together',
          destination: { location_id: form.destinationId, ...(form.destinationRoomId ? { room_id: form.destinationRoomId } : {}) },
          scope: form.scope,
          ...(form.afterArrivalKey ? { after_arrival: { type: 'pair', pose_key: form.afterArrivalKey } } : {}),
        }
        payload.trigger = { kind: 'standing' }
        payload.target_count = 0
      }
      setSubmitting(true)
      try {
        if (editingId) {
          await apiPatch(`/intents/${encodeURIComponent(editingId)}`, payload)
          toast(t('Intent updated'))
        } else {
          await apiPost('/intents', payload)
          toast(t('Intent created'))
        }
        resetForm()
        await reload()
      } catch (err) {
        toast(t('Save failed') + ': ' + (err as Error).message, 'error')
      } finally {
        setSubmitting(false)
      }
    },
    [form, editingId, editParticipants, reload, resetForm, t, toast],
  )

  const handleComplete = useCallback(
    async (id: string) => {
      try {
        await apiPost(`/intents/${encodeURIComponent(id)}/complete`, {})
        await reload()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      }
    },
    [reload, t, toast],
  )

  const handleCancel = useCallback(async (id: string) => {
    try {
      await apiPatch(`/intents/${encodeURIComponent(id)}`, { status: 'cancelled' })
      await reload()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [reload, t, toast])

  // The click arms the in-app question, the dialog at the end deletes.
  const [pendingDelete, setPendingDelete] = useState<{ id: string; title: string } | null>(null)
  const handleDelete = useCallback((id: string, title: string) => {
    setPendingDelete({ id, title })
  }, [])
  const confirmDelete = useCallback(
    async () => {
      const target = pendingDelete
      setPendingDelete(null)
      if (!target) return
      try {
        await apiDelete(`/intents/${encodeURIComponent(target.id)}`)
        await reload()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      }
    },
    [pendingDelete, reload, t, toast],
  )

  return (
    <div className="ga-page-scroll">
      {cleanupOpen ? <CleanupDialog
        owners={[...new Set((intents || []).map((it) => it.owner).filter(Boolean))].sort()}
        ownerLabel={(owner) => characters.find((c) => c.name === owner)?.display_name || owner}
        expiryLabel={expiresAtLabel}
        onClose={() => setCleanupOpen(false)}
        onApplied={(result) => {
          setCleanupOpen(false)
          toast(cleanupCounts(result, t))
          void reload()
        }}
      /> : null}
      <h2 style={{ fontSize: 16, marginBottom: 6 }}>{t('Intents — Plans & Tasks')}</h2>

      <section className="ga-sched-section">
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 12 }}>
          <h3 style={{ margin: 0 }}>{t('All intents')}</h3>
          <button type="button" className="ga-btn ga-btn-sm" onClick={() => setCleanupOpen(true)}>
            {t('Clean up…')}
          </button>
        </div>
        <p className="ga-sched-muted">
          {t(
            'One store for human-assigned tasks and character-owned plans. Characters create their own via reflection and in-chat decisions; admins can add, complete or remove any intent here.',
          )}
        </p>
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8, marginBottom: 12 }}>
          <select className="ga-input" style={{ width: 'auto', maxWidth: '100%' }} aria-label={t('Character')} value={view.character} onChange={(e) => setView((v) => ({ ...v, character: e.target.value }))}>
            <option value="">{t('All characters')}</option>
            {characterNames.map((name) => <option key={name} value={name}>{characters.find((c) => c.name === name)?.display_name || name}</option>)}
          </select>
          <select className="ga-input" style={{ width: 'auto', maxWidth: '100%' }} aria-label={t('Status')} value={view.status} onChange={(e) => setView((v) => ({ ...v, status: e.target.value as IntentView['status'] }))}>
            <option value="active">{t('Active')}</option><option value="done">{t('Done')}</option>
            <option value="expired">{t('Expired')}</option><option value="cancelled">{t('Cancelled')}</option><option value="all">{t('All')}</option>
          </select>
          <select className="ga-input" style={{ width: 'auto', maxWidth: '100%' }} aria-label={t('Source')} value={view.source} onChange={(e) => setView((v) => ({ ...v, source: e.target.value as IntentView['source'] }))}>
            <option value="">{t('All sources')}</option><option value="human">{t('human')}</option><option value="character">{t('character')}</option>
          </select>
          <select className="ga-input" style={{ width: 'auto', maxWidth: '100%' }} aria-label={t('Trigger')} value={view.trigger} onChange={(e) => setView((v) => ({ ...v, trigger: e.target.value }))}>
            <option value="">{t('All triggers')}</option>
            <option value="standing">{t('standing')}</option><option value="now">{t('now')}</option>
            <option value="at_location">{t('at_location')}</option><option value="at_time">{t('at_time')}</option><option value="daily">{t('daily')}</option>
          </select>
          <input className="ga-input" style={{ width: 'auto', maxWidth: '100%' }} type="search" aria-label={t('Search')} placeholder={t('Search')} value={view.search} onChange={(e) => setView((v) => ({ ...v, search: e.target.value }))} />
          <span className="ga-sched-muted">{t('{shown} of {total}').replace('{shown}', String(visibleIntents.length)).replace('{total}', String(intents?.length || 0))}</span>
          <button type="button" className="ga-btn ga-btn-sm" onClick={() => setView(DEFAULT_VIEW)}>{t('Reset filters')}</button>
        </div>
        <table className="ga-sched-table">
          <thead>
            <tr>
              {sortHeader('title', 'Title')}
              {sortHeader('owner', 'Owner')}
              {sortHeader('source', 'Source')}
              {sortHeader('trigger', 'Trigger')}
              {sortHeader('priority', 'Priority')}
              {sortHeader('expires', 'Expires')}
              {sortHeader('progress', 'Progress')}
              <th>{t('Last 7 days')}</th>
              {sortHeader('status', 'Status')}
              {sortHeader('created', 'Created')}
              <th />
            </tr>
          </thead>
          <tbody>
            {error ? (
              <tr>
                <td colSpan={11}>error: {error}</td>
              </tr>
            ) : intents === null ? (
              <tr>
                <td colSpan={11} className="ga-sched-muted">
                  {t('Loading…')}
                </td>
              </tr>
            ) : intents.length === 0 ? (
              <tr>
                <td colSpan={11} className="ga-sched-muted">
                  {t('No intents yet.')}
                </td>
              </tr>
            ) : visibleIntents.length === 0 ? (
              <tr><td colSpan={11} className="ga-sched-muted">{t('No intents match the filters.')}</td></tr>
            ) : (
              visibleIntents.map((it) => {
                const active = it.status === 'active'
                const parts = Object.keys(it.participants || {})
                const owner = it.owner || parts[0] || '—'
                return (
                  <tr key={it.id}>
                    <td>
                      <div>{it.title}</div>
                      {it.description ? (
                        <div className="ga-sched-muted" style={{ fontSize: 12 }}>
                          {it.description}
                        </div>
                      ) : null}
                      {it.action?.type ? (
                        <div className="ga-sched-muted" style={{ fontSize: 12 }}>
                          {t('Shared trip')}: {locName(it.action.destination?.location_id || '')}
                          {it.action.destination?.room_id ? ` / ${locations.find((l) => l.id === it.action?.destination?.location_id)?.rooms?.find((r) => r.id === it.action?.destination?.room_id)?.name || it.action.destination.room_id}` : ''}
                          <div>{t('After arrival')}: {it.action.after_arrival?.pose_key || t('Travel only')}</div>
                          <div>{t('Scope')}: {it.action.scope === 'party' ? t('Entire party') : t('Pair only')}</div>
                          <div>{t('Trip phase')}: {t(TRIP_PHASE_LABELS[it.meta?.travel?.phase || ''] || it.meta?.travel?.phase || '—')}{it.meta?.travel?.reason ? ` — ${it.meta.travel.reason}` : ''}</div>
                          <div>{t('Participants')}: {(it.meta?.travel?.expected_members || parts).join(', ')}</div>
                        </div>
                      ) : null}
                    </td>
                    <td>
                      <span className="ga-tag ga-tag-char">{owner}</span>
                      {parts.length > 1 ? (
                        <span className="ga-sched-muted"> +{parts.length - 1}</span>
                      ) : null}
                    </td>
                    <td>
                      <span className={it.source === 'human' ? 'ga-tag ga-tag-admin' : 'ga-tag'}>
                        {t(it.source)}
                      </span>
                    </td>
                    <td>{triggerSummary(it, locName, t)}</td>
                    <td>{t(PRIORITY_LABELS[it.priority] || 'Normal')}</td>
                    <td className="ga-sched-muted" style={{ fontSize: 12 }}>
                      {expiresAtLabel(it.expires_at) || '—'}
                    </td>
                    <td>{(it.target_count || 0) > 0
                      ? `${Math.max(0, ...Object.values(it.participants || {}).map((p) => p.progress?.length || 0))}/${it.target_count}`
                      : '—'}</td>
                    <td>{it.meta?.repeat_state?.log.slice(-7).map((entry) => (
                      <span key={entry.day} title={`${entry.day}: ${t(entry.result)} (${entry.count})`}>
                        {entry.result === 'done' ? '✓' : '✗'}
                      </span>
                    ))}</td>
                    <td className={active ? 'ga-status-ok' : 'ga-status-paused'}>
                      {t(it.status)}
                      {it.status === 'expired' && it.meta?.expired_reason
                        ? ` — ${t(EXPIRY_REASON_LABELS[it.meta.expired_reason] || it.meta.expired_reason)}`
                        : ''}
                    </td>
                    <td className="ga-sched-muted" style={{ fontSize: 12, whiteSpace: 'nowrap' }}>{it.created_at?.slice(0, 16).replace('T', ' ') || '—'}</td>
                    <td className="ga-or-actions-col">
                      <button className="ga-btn ga-btn-sm" disabled={!!it.action?.type} onClick={() => handleEdit(it)}>
                        {t('Edit')}
                      </button>{' '}
                      {active && !it.action?.type ? (
                        <button className="ga-btn ga-btn-sm" onClick={() => handleComplete(it.id)}>
                          {t('Complete')}
                        </button>
                      ) : null}{' '}
                      {active ? <button className="ga-btn ga-btn-sm ga-btn-danger" onClick={() => handleCancel(it.id)}>{t('Cancel intent')}</button> : null}{' '}
                      <button
                        className="ga-btn ga-btn-sm ga-btn-danger"
                        onClick={() => handleDelete(it.id, it.title)}
                      >
                        {t('Delete')}
                      </button>
                    </td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </section>

      <section className="ga-sched-section">
        <h3>{editingId ? t('Edit intent') : t('Create intent')}</h3>
        <form className="ga-sched-form" onSubmit={handleSubmit}>
          <div className="ga-sched-form-row">
            <div className="ga-sched-field">
              <label>{t('Plan type')}</label>
              <select className="ga-input" value={form.actionKind} disabled={!!editingId}
                onChange={(e) => setForm((f) => ({ ...f, actionKind: e.target.value as FormState['actionKind'], triggerKind: 'standing', repeat: '', targetCount: 0, progressType: '', participants: [] }))}>
                <option value="plan">{t('Ordinary plan')}</option>
                {actionTypes.includes('travel_together') ? <option value="travel_together">{t('Shared trip')}</option> : null}
              </select>
            </div>
            {form.actionKind === 'travel_together' ? <>
              <div className="ga-sched-field">
                <label>{t('Destination')}</label>
                <select className="ga-input" required value={form.destinationId}
                  onChange={(e) => setForm((f) => ({ ...f, destinationId: e.target.value, destinationRoomId: '' }))}>
                  <option value="">{t('— pick location —')}</option>
                  {locations.map((l) => <option key={l.id} value={l.id}>{l.name || l.id}</option>)}
                </select>
              </div>
              <div className="ga-sched-field">
                <label>{t('Destination room (optional)')}</label>
                <select className="ga-input" value={form.destinationRoomId}
                  onChange={(e) => setForm((f) => ({ ...f, destinationRoomId: e.target.value }))}>
                  <option value="">{t('Default arrival room')}</option>
                  {(locations.find((l) => l.id === form.destinationId)?.rooms || []).map((r) => <option key={r.id} value={r.id}>{r.name || r.id}</option>)}
                </select>
              </div>
              <div className="ga-sched-field">
                <label>{t('Scope')}</label>
                <select className="ga-input" value={form.scope} onChange={(e) => setForm((f) => ({ ...f, scope: e.target.value as FormState['scope'] }))}>
                  <option value="pair">{t('Pair only')}</option>
                  <option value="party">{t('Entire party')}</option>
                </select>
              </div>
              <div className="ga-sched-field">
                <label>{t('After arrival')}</label>
                <select className="ga-input" value={form.afterArrivalKey}
                  onChange={(e) => setForm((f) => ({ ...f, afterArrivalKey: e.target.value }))}>
                  <option value="">{t('Travel only')}</option>
                  {sharedActivityOptions.map((key) => <option key={key} value={key}>{key}</option>)}
                </select>
              </div>
              {form.afterArrivalKey ? <p className="ga-sched-muted">{t('The paired activity requires exactly two trip members and a separate invitation after arrival.')}</p> : null}
              <p className="ga-sched-muted">{t('The owner leads. Pick one new companion; consent is required. Entire party explicitly includes existing members. Pair only never removes existing members. Cancel and create a new trip to change its destination or group.')}</p>
            </> : null}
          </div>
          <div className="ga-sched-form-row">
            <div className="ga-sched-field" style={{ flex: 1, minWidth: 220 }}>
              <label>{t('Title')}</label>
              <input
                className="ga-input"
                value={form.title}
                onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
                placeholder={t('e.g. Photoshoot in the park')}
                required
              />
            </div>
            <div className="ga-sched-field">
              <label>{t('Owner')}</label>
              <select
                className="ga-input"
                value={form.owner}
                onChange={(e) => setForm((f) => ({ ...f, owner: e.target.value }))}
                required
              >
                <option value="">{t('— pick character —')}</option>
                {characters.map((c) => (
                  <option key={c.name} value={c.name}>
                    {c.display_name || c.name}
                  </option>
                ))}
              </select>
            </div>
            <div className="ga-sched-field">
              <label>{t('Priority')}</label>
              <select
                className="ga-input"
                value={form.priority}
                onChange={(e) => setForm((f) => ({ ...f, priority: parseInt(e.target.value, 10) }))}
              >
                {[1, 2, 3, 4, 5].map((p) => (
                  <option key={p} value={p}>
                    {p} — {t(PRIORITY_LABELS[p])}
                  </option>
                ))}
              </select>
            </div>
            {form.actionKind === 'plan' ? <>
              <div className="ga-sched-field">
                <label>{t('Repeat')}</label>
                <select className="ga-input" value={form.repeat}
                  onChange={(e) => setForm((f) => ({ ...f, repeat: e.target.value as FormState['repeat'], triggerKind: 'standing' }))}>
                  <option value="">{t('never')}</option>
                  <option value="daily">{t('daily')}</option>
                </select>
              </div>
              <div className="ga-sched-field">
                <label>{t('Count')}</label>
                <input className="ga-input" type="number" min={0} step={1} required value={form.targetCount}
                  onChange={(e) => setForm((f) => ({ ...f, targetCount: Number(e.target.value) }))} />
                <span className="ga-sched-muted">{t('0 = no count')}</span>
              </div>
              <div className="ga-sched-field">
                <label>{t('Counts')}</label>
                <select className="ga-input" value={form.progressType}
                  onChange={(e) => setForm((f) => ({ ...f, progressType: e.target.value }))}>
                  <option value="">{t('any')}</option>
                  {[...new Set([...progressTypes, ...(form.progressType ? [form.progressType] : [])])].map((kind) => <option key={kind} value={kind}>{kind}</option>)}
                </select>
              </div>
            </> : null}
            <div className="ga-sched-field">
              <label>{t('Trigger')}</label>
              <select
                className="ga-input"
                disabled={form.actionKind === 'travel_together'}
                value={form.triggerKind}
                onChange={(e) => setForm((f) => ({ ...f, triggerKind: e.target.value as TriggerKind }))}
              >
                {form.repeat === 'daily' ? <>
                  <option value="standing">{t('all day')}</option>
                  <option value="at_time">{t('daily at')}</option>
                </> : <>
                  <option value="standing">{t('standing (ongoing)')}</option>
                  <option value="now">{t('now (bump immediately)')}</option>
                  <option value="at_location">{t('on entering a location')}</option>
                  <option value="at_time">{t('at a date/time')}</option>
                </>}
              </select>
            </div>
            {form.triggerKind === 'at_location' ? (
              <div className="ga-sched-field">
                <label>{t('Location')}</label>
                <select
                  className="ga-input"
                  value={form.locationId}
                  onChange={(e) => setForm((f) => ({ ...f, locationId: e.target.value }))}
                >
                  <option value="">{t('— pick location —')}</option>
                  {locations.map((l) => (
                    <option key={l.id} value={l.id}>
                      {l.name || l.id}
                    </option>
                  ))}
                </select>
              </div>
            ) : null}
            {form.triggerKind === 'at_time' && form.repeat === 'daily' ? (
              <div className="ga-sched-field">
                <label>{t('daily at')}</label>
                <input className="ga-input" type="time" required value={form.dailyAt}
                  onChange={(e) => setForm((f) => ({ ...f, dailyAt: e.target.value }))} />
              </div>
            ) : null}
            {form.triggerKind === 'at_time' && !form.repeat ? (
              <div className="ga-sched-field">
                <label>{t('Starts in (game time)')}</label>
                <select
                  className="ga-input"
                  value={form.runInMin}
                  onChange={(e) => setForm((f) => ({ ...f, runInMin: parseInt(e.target.value, 10) }))}
                >
                  {editingId && form.runDate ? (
                    <option value={0}>
                      {t('keep current')} ({gameStampLabel(form.runDate)})
                    </option>
                  ) : (
                    <option value={0}>—</option>
                  )}
                  {RUN_IN_OPTIONS.map((d) => (
                    <option key={d.value} value={d.value}>
                      {t(d.label)}
                    </option>
                  ))}
                </select>
              </div>
            ) : null}
            <div className="ga-sched-field">
              <label>{t('Outfit hint (optional)')}</label>
              <input
                className="ga-input"
                value={form.outfitHint}
                onChange={(e) => setForm((f) => ({ ...f, outfitHint: e.target.value }))}
              />
            </div>
            <div className="ga-sched-field">
              <label>{editingId ? t('Expiry (change)') : t('Expiry')}</label>
              <select
                className="ga-input"
                disabled={form.repeat === 'daily'}
                value={form.durationMin}
                onChange={(e) => setForm((f) => ({ ...f, durationMin: parseInt(e.target.value, 10) }))}
              >
                {editingId ? <option value={0}>{t('keep current')}</option> : null}
                {DURATION_OPTIONS.map((d) => (
                  <option key={d.value} value={d.value}>
                    {t(d.label)}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <div className="ga-sched-form-row">
            <div className="ga-sched-field" style={{ flex: 1, minWidth: 320 }}>
              <label>{t('Description (optional)')}</label>
              <input
                className="ga-input"
                value={form.description}
                onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
                placeholder={t('What should happen?')}
              />
            </div>
            <div className="ga-sched-field" style={{ minWidth: 220 }}>
              <label>{form.actionKind === 'travel_together' ? t('Companion') : t('Additional participants (optional)')}</label>
              <select
                className="ga-input"
                multiple={form.actionKind === 'plan'}
                size={3}
                value={form.actionKind === 'plan' ? form.participants : form.participants[0] || ''}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    participants: Array.from(e.target.selectedOptions, (o) => o.value),
                  }))
                }
              >
                {form.actionKind === 'travel_together' ? <option value="">{t('— pick character —')}</option> : null}
                {characters
                  .filter((c) => c.name !== form.owner)
                  .map((c) => (
                    <option key={c.name} value={c.name}>
                      {c.display_name || c.name}
                    </option>
                  ))}
              </select>
            </div>
          </div>
          <div className="ga-sched-form-row">
            <button type="submit" className="ga-btn ga-btn-primary" disabled={submitting}>
              {submitting
                ? t('Saving…')
                : editingId
                  ? t('Save changes')
                  : t('Create')}
            </button>
            {editingId ? (
              <button type="button" className="ga-btn" onClick={resetForm} disabled={submitting}>
                {t('Cancel')}
              </button>
            ) : null}
          </div>
        </form>
      </section>

      <ConfirmDialog
        open={!!pendingDelete}
        title={t('Delete intent')}
        message={t('Intent "{x}" is deleted; the character stops pursuing it.')
          .replace('{x}', pendingDelete ? pendingDelete.title : '')}
        confirmLabel={t('Delete')}
        danger
        onConfirm={() => { void confirmDelete() }}
        onClose={() => setPendingDelete(null)}
      />
    </div>
  )
}
