/**
 * SceneView — hybrid renderer for a list of scene lines (dialogue + narrated
 * ambient). Shared on purpose: the Observer tab uses it now, the player room UI
 * (Phase 2) reuses the same component. plan-room-conversation.
 *
 * It renders whatever it is handed — it does NOT filter. Confidentiality is
 * enforced upstream (the subjective stream never carries whispered content).
 */
import type { ReactNode } from 'react'
import { useI18n } from './I18nProvider'
import { formatTime } from './clockFormat'
import { clockSettings, useClockSettings } from './clockSettings'

export interface SceneLine {
  /** Perception row id — stable across polls, unique within one history.
   *  Only the `/play/scene` payload carries it; the objective observer view
   *  does not, so nothing may depend on it being there. */
  id?: number
  ts: string
  speaker?: string
  content?: string
  /** perception kind (spoken_self|in_room|nearby|whisper_meta|inattentive_meta|distant_shout) or
   *  'utterance' for objective rows. `nearby` = heard out in the open, where
   *  the hearing radius takes the room's place (E6). */
  kind?: string
  addressees?: string[]
  /** objective view only: whisper|normal|shout */
  volume?: string
  meta?: Record<string, unknown>
}

function clockOf(ts: string): string {
  // A SYSTEM stamp in the configured world timezone and clock format (so
  // whether seconds show is the admin's setting, not this file's decision).
  return formatTime(ts, clockSettings()) || ts
}

function addresseesOf(line: SceneLine): string[] {
  if (line.addressees && line.addressees.length) return line.addressees
  const m = line.meta?.addressees
  return Array.isArray(m) ? (m as string[]) : []
}

function speakerOf(line: SceneLine): string {
  return line.speaker || (line.meta?.speaker as string) || '?'
}

/** Token usage of the LLM call that produced the line, as `meta.llm_usage`.
 *  The server sends it to admins only (`/play/scene`), so its mere presence is
 *  the switch. `cached_tokens` missing means the backend reported no cache
 *  figure at all — shown as such, because that is not a cold cache (0). */
interface LineUsage {
  text: string
  /** share of the prompt served from the backend's cache, null = not reported */
  pct: number | null
}

function usageOf(line: SceneLine, t: (en: string) => string): LineUsage | null {
  const u = line.meta?.llm_usage
  if (!u || typeof u !== 'object') return null
  const usage = u as Record<string, unknown>
  // 0/missing = the backend reported no usage at all; the prompt part is then
  // left out rather than shown as "0 tok".
  const prompt = Number(usage.prompt_tokens) || 0
  const model = typeof usage.model === 'string' ? usage.model : ''
  const cached = typeof usage.cached_tokens === 'number' ? usage.cached_tokens : null
  const pct = cached === null ? null : (prompt > 0 ? Math.round((cached / prompt) * 100) : 0)
  const parts: string[] = []
  if (prompt > 0) parts.push(t('prompt {prompt} tok').replace('{prompt}', prompt.toLocaleString()))
  parts.push(cached === null
    ? t('cache not reported')
    : t('cached {cached} ({pct}%)')
      .replace('{cached}', cached.toLocaleString())
      .replace('{pct}', String(pct)))
  if (model) parts.push(model)
  return { text: parts.join(' · '), pct }
}

export interface ThinkingInfo {
  name: string
  /** true = antwortet (sichtbarer Chat-Turn), false = denkt (Hintergrund). */
  responding?: boolean
}

/** The class a highlighted row carries IN ADDITION to `ga-list-row`. It is set
 *  only when `highlightedId` names the row — nobody who leaves that prop out
 *  ever sees it, and the package ships no rule for it: the host that asks for
 *  a highlight styles it (the 3D HUD does, `/play` does not use it). */
export const SCENE_ROW_ACTIVE_CLASS = 'scene-row-active'

/** The attribute a row's id is written to, so a host can measure/address rows
 *  in the DOM (`[data-scene-id="…"]`) without a ref per line. Always set when
 *  the line has an id — an attribute is invisible. */
export const SCENE_ROW_ID_ATTR = 'data-scene-id'

export function SceneView({ lines, emptyHint, thinking, onOpenImage,
                            highlightedId, onRowHover }: {
  lines: SceneLine[]
  emptyHint?: string
  thinking?: ThinkingInfo[]
  /** Optional: open an attached scene image (e.g. in a Lightbox). */
  onOpenImage?: (url: string) => void
  /** Optional: id of the row to mark as highlighted (see
   *  `SCENE_ROW_ACTIVE_CLASS`). Left out = no row is ever marked. */
  highlightedId?: number | null
  /** Optional: the pointer entered a row (its id) or left it (`null`).
   *  Left out = no pointer handlers are attached at all. */
  onRowHover?: (id: number | null) => void
}) {
  // Subscribe to the shared clock settings so the stamp helpers above
  // re-render once the server-configured format and timezone arrive.
  useClockSettings()
  const { t } = useI18n()
  const thinkers = thinking || []
  if (!lines.length && !thinkers.length) {
    return <div className="ga-list-empty">{emptyHint || t('No lines')}</div>
  }
  return (
    <div className="ga-list" style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      {lines.map((line, i) => (
        // Key on the row id where there is one (stable across polls); the
        // objective observer view has none and keeps the index.
        <SceneRow key={line.id ?? i} line={line} onOpenImage={onOpenImage}
          highlighted={highlightedId != null && line.id === highlightedId}
          onRowHover={onRowHover} />
      ))}
      {thinkers.map((info) => (
        <div key={`thinking-${info.name}`} className="ga-list-row" style={{ display: 'flex', gap: 8, alignItems: 'baseline', opacity: 0.75 }}>
          <span className="ga-list-row-sub" style={{ fontVariantNumeric: 'tabular-nums', opacity: 0.5, fontSize: '0.75em' }} />
          <span className="ga-list-row-main" style={{ flex: 1 }}>
            <strong>{info.name}</strong>{' '}
            <span style={{ opacity: 0.7, fontStyle: 'italic' }}>
              {info.responding ? t('is responding') : t('is thinking')}
            </span>{' '}
            <span className="player-thinking-dots" aria-hidden="true">
              <span className="player-thinking-dot" />
              <span className="player-thinking-dot" />
              <span className="player-thinking-dot" />
            </span>
          </span>
        </div>
      ))}
    </div>
  )
}

function SceneRow({ line, onOpenImage, highlighted, onRowHover }: {
  line: SceneLine
  onOpenImage?: (url: string) => void
  /** Adds `SCENE_ROW_ACTIVE_CLASS`; false/absent leaves the markup as it was. */
  highlighted?: boolean
  onRowHover?: (id: number | null) => void
}) {
  const { t } = useI18n()
  // Row hooks for a host that wants a highlight. Without `onRowHover` no
  // handler is attached, without `highlighted` no class is added — a caller
  // that passes neither gets exactly the markup of before.
  const rowProps = {
    [SCENE_ROW_ID_ATTR]: line.id,
    onMouseEnter: onRowHover && line.id != null
      ? () => onRowHover(line.id as number) : undefined,
    onMouseLeave: onRowHover ? () => onRowHover(null) : undefined,
  }
  const rowClass = 'ga-list-row' + (highlighted ? ` ${SCENE_ROW_ACTIVE_CLASS}` : '')
  const speaker = speakerOf(line)
  const addr = addresseesOf(line)
  const time = clockOf(line.ts)
  // Attached image (avatar showed something): rendered as a small thumbnail
  // under the line. Click opens it via onOpenImage (Lightbox) or in a new tab.
  const imageUrl = (line.meta?.image_url as string) || ''
  const usage = usageOf(line, t)

  // Event verdict (resolved/unresolved) — its own coloured block below the narrator.
  const verdict = line.meta?.event_verdict as string | undefined
  if (verdict === 'resolved' || verdict === 'unresolved') {
    const resolved = verdict === 'resolved'
    return (
      <div className={rowClass} {...rowProps} style={{
        display: 'flex', gap: 8, alignItems: 'baseline', padding: '4px 8px',
        margin: '2px 0', borderRadius: 6,
        borderLeft: `4px solid ${resolved ? '#3fa45a' : '#e0843c'}`,
        background: resolved ? 'rgba(63,164,90,0.16)' : 'rgba(224,132,60,0.16)',
      }}>
        <span style={{ flex: '0 0 auto', fontSize: '0.75em', fontWeight: 700,
          color: resolved ? '#7ed79a' : '#f0a868' }}>
          {resolved ? `✓ ${t('Event resolved')}` : `⚠ ${t('Event unresolved')}`}
        </span>
        <span style={{ flex: 1, opacity: 0.85, fontStyle: 'italic' }}>{line.content}</span>
      </div>
    )
  }

  let body: ReactNode

  if (line.kind === 'inattentive_meta') {
    body = <em style={{ opacity: 0.65 }}>{speaker} {t('says something you do not catch.')}</em>
  } else if (line.meta?.relationship) {
    // Relationship change (display-only, never in LLM transcripts): subtle
    // rosé meta line — "💞 Kai ⇄ Bianca Voss: neutral → acquaintance".
    body = (
      <em style={{ color: '#c98ba8', opacity: 0.85, fontSize: '0.9em' }}>
        {line.content}
      </em>
    )
  } else if (line.meta?.narrator === true) {
    // Narrator prose (Act/Storyteller): set apart by colour — gold + italic, so
    // it is clearly distinct from character dialogue.
    //
    // The narrator is recognised by the SERVER'S MARK and by nothing else:
    // `/play/scene` sets `meta.narrator` on every storyteller line, in every
    // language (`app/routes/play.py`). `speaker` on those rows is a LOCALIZED
    // label — "Storyteller" in an English world, "Erzähler" in a German one —
    // so a name test is a test against a rendering and misses every world
    // whose language is not the one hardcoded.
    body = (
      <span style={{ fontStyle: 'italic', color: '#d6b06a' }}>
        <strong style={{ opacity: 0.85 }}>{speaker}</strong>: {line.content}
      </span>
    )
  } else if (line.kind === 'whisper_meta') {
    // third party: knows the fact, never the content
    const to = addr.length ? addr.join(', ') : t('someone')
    body = <em style={{ opacity: 0.65 }}>🤫 {speaker} {t('whispers something to')} {to}</em>
  } else if (line.kind === 'distant_shout') {
    body = (
      <span style={{ opacity: 0.8 }}>
        ‹ {t('from afar')} — <strong>{speaker}</strong>: {line.content} ›
      </span>
    )
  } else {
    // spoken_self | in_room | objective utterance — make the volume visible:
    // whisper = grey/dimmed + 🤫, shout = bold + UPPERCASE + 📢.
    // The addressee stays as a small arrow (information separate from volume).
    const isWhisper = line.volume === 'whisper'
    const isShout = line.volume === 'shout'
    const icon = isWhisper ? '🤫 ' : isShout ? '📢 ' : ''
    const toArrow = addr.length ? <span style={{ opacity: 0.5 }}> → {addr.join(', ')}</span> : null
    const content = isShout ? (line.content || '').toUpperCase() : line.content
    const volStyle = isWhisper
      ? { opacity: 0.5 }                 // leise → gedimmt/grau
      : isShout
        ? { fontWeight: 700 as const }   // schreien → fett (+ Caps am Inhalt)
        : {}
    body = (
      <span style={volStyle}>
        {icon}<strong>{speaker}</strong>{toArrow}: {content}
      </span>
    )
  }

  return (
    <div className={rowClass} {...rowProps} style={{ display: 'flex', gap: 8, alignItems: 'baseline' }}>
      <span className="ga-list-row-sub" style={{ fontVariantNumeric: 'tabular-nums', opacity: 0.5, fontSize: '0.75em' }}>
        {time}
      </span>
      <span className="ga-list-row-main" style={{ flex: 1 }}>
        {body}
        {imageUrl && (
          <span style={{ display: 'block', marginTop: 4 }}>
            <img
              src={imageUrl}
              alt={t('Attached image')}
              onClick={() => (onOpenImage ? onOpenImage(imageUrl) : window.open(imageUrl, '_blank'))}
              style={{
                maxWidth: 180, maxHeight: 180, borderRadius: 6, cursor: 'pointer',
                border: '1px solid var(--border, #30363d)', display: 'block',
              }}
            />
          </span>
        )}
        {usage && (
          <span style={{
            display: 'block', fontSize: '0.7em', opacity: 0.6,
            fontVariantNumeric: 'tabular-nums',
            // green = most of the prompt came from the cache, amber = little
            // did, grey = the backend does not say
            color: usage.pct === null ? undefined : usage.pct >= 50 ? '#3fa45a' : '#e0843c',
          }}>
            ⚡ {usage.text}
          </span>
        )}
      </span>
      <span className="ga-list-row-sub" style={{ opacity: 0.35, fontSize: '0.7em' }}>{line.kind}</span>
    </div>
  )
}
