import { useCallback, useEffect, useMemo, useState } from 'react'
import { useI18n } from '../../i18n/I18nProvider'
import { ApiError, apiDelete, apiGet, apiPost, apiPut } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { loadCharacters, loadLocations, type CharacterRef, type LocationRef } from '../../lib/refs'
import { Field } from '@anima/player-ui'
import { ConfirmDialog } from '@anima/player-ui'
import { DetailToolbar } from '../../components/DetailToolbar'
import { ListHeader } from '../../components/ListHeader'
import { ListPane } from '../../components/ListPane'
import { ExportButton, ImportButton, PublishButton } from '../../components/ImportExport'
import { roomLabel } from '../world/worldTypes'
import { InfluenceRuleFields, type Influence, type PairCondition, type InfluenceValidation } from './InfluenceRuleFields'

type RuleType = 'block' | 'force' | 'discover' | 'modify' | 'influence'
type TargetScope = 'location' | 'any_room' | 'danger_level' | 'skill'

interface Quantity {
  id: string
  label: string
  description: string
}

interface ForceAction {
  go_to?: 'stay' | 'home'
  // B1: state flags are the authority — the executor applies these
  // (is_sleeping true/false wakes from off-map too). set_activity is dead.
  set_flags?: Record<string, boolean | string>
}

interface RuleTarget {
  scope?: TargetScope
  location?: string
  rooms?: string[]
  skills?: string[]
  action?: 'enter' | 'leave'
  min_danger_level?: number
}

interface Rule {
  id?: string
  name?: string
  type?: RuleType
  character?: string
  target?: RuleTarget
  modify?: { quantity: string; factor: number }
  influence?: Influence
  actor_condition?: string
  pair_conditions?: PairCondition[]
  force_action?: ForceAction
  /** The field the server reads (`rules.check_discover_rules`), top-level. */
  probability?: number
  /** Dead shape this tab used to WRITE — never read by the server, so no
   *  discover rule made here ever fired. Kept only to pre-fill the form of
   *  such a rule once; saving replaces it with `probability`. */
  discover?: { probability?: number }
  condition?: string
  message?: string
  _origin?: string
}

interface DraftRule {
  id: string
  name: string
  type: RuleType
  character: string
  target_storage: 'world' | 'shared'
  target_scope: TargetScope
  target_location: string
  target_rooms: string[]
  target_skills: string[]
  target_action: 'enter' | 'leave'
  target_min_danger: number
  force_go_to: 'stay' | 'home'
  force_sleep: '' | 'sleep' | 'wake'
  modify_quantity: string
  modify_factor: number
  discover_probability: number
  condition: string
  influence: Influence
  actor_condition: string
  pair_conditions: PairCondition[]
  localized: Record<string, string>
  message: string
  origin: string
  isNew: boolean
}

const EMPTY_DRAFT: DraftRule = {
  id: '',
  name: '',
  type: 'block',
  character: '',
  target_storage: 'world',
  target_scope: 'location',
  target_location: '',
  target_rooms: [],
  target_skills: [],
  target_action: 'enter',
  target_min_danger: 3,
  force_go_to: 'stay',
  force_sleep: '',
  modify_quantity: 'travel_speed',
  modify_factor: 1,
  discover_probability: 0.05,
  condition: '',
  influence: { actor: '', recipient: '', stat: '', direction: 'both', factor: 1 },
  actor_condition: '',
  pair_conditions: [],
  localized: {},
  message: '',
  origin: '',
  isNew: true,
}

function ruleToDraft(r: Rule): DraftRule {
  const target = r.target || {}
  const force = r.force_action || {}
  return {
    id: r.id || '',
    name: r.name || '',
    type: r.type || 'block',
    character: r.character || '',
    target_storage: r._origin === 'shared' ? 'shared' : 'world',
    target_scope: target.scope || 'location',
    target_location: target.location || '',
    target_rooms: [...(target.rooms || [])],
    target_skills: [...(target.skills || [])],
    target_action: target.action || 'enter',
    target_min_danger: target.min_danger_level ?? 3,
    force_go_to: force.go_to || 'stay',
    force_sleep: force.set_flags?.is_sleeping === true ? 'sleep'
      : force.set_flags?.is_sleeping === false ? 'wake' : '',
    modify_quantity: r.modify?.quantity || 'travel_speed',
    modify_factor: r.modify?.factor ?? 1,
    // The contract field first; the old nested one only so a rule written by
    // an earlier version of this tab opens with the number its author meant
    // instead of the default. Form pre-fill only — nothing reads the nested
    // shape at runtime, and `draftToRule` writes the flat field back.
    discover_probability: r.probability ?? r.discover?.probability ?? 0.05,
    condition: r.condition || '',
    influence: { ...(r.influence || EMPTY_DRAFT.influence) },
    actor_condition: r.actor_condition || '',
    pair_conditions: (r.pair_conditions || []).map(pair => ({ ...pair })),
    localized: Object.fromEntries(Object.entries(r).filter(([key, value]) =>
      /^(name|message)_[a-z]+$/.test(key) && typeof value === 'string')),
    message: r.message || '',
    origin: r._origin || 'world',
    isNew: false,
  }
}

function draftToRule(d: DraftRule): Rule {
  const r: Rule = {
    ...d.localized,
    id: d.id || undefined,
    name: d.name.trim(),
    type: d.type,
    condition: d.condition.trim(),
    message: d.message.trim(),
  }
  if (d.type !== 'influence' && d.character.trim()) r.character = d.character.trim()

  if (d.type === 'block') {
    const target: RuleTarget = { scope: d.target_scope, action: d.target_action }
    if (d.target_scope === 'location') {
      target.location = d.target_location
      if (d.target_rooms.length) target.rooms = d.target_rooms
    } else if (d.target_scope === 'skill') {
      target.skills = d.target_skills
      delete target.action
    } else if (d.target_scope === 'danger_level') {
      target.min_danger_level = d.target_min_danger
    }
    r.target = target
  } else if (d.type === 'force') {
    r.force_action = { go_to: d.force_go_to }
    if (d.force_sleep) {
      r.force_action.set_flags = { is_sleeping: d.force_sleep === 'sleep' }
    }
  } else if (d.type === 'modify') {
    r.modify = { quantity: d.modify_quantity, factor: Math.max(0.1, Math.min(5, d.modify_factor)) }
  } else if (d.type === 'discover') {
    // TOP-LEVEL, because that is what the server reads
    // (`app/models/rules.py`, and shared/rules/rules.json writes it that way
    // too). The rule object is rebuilt from scratch here, so saving also
    // drops the dead nested `discover` key.
    r.probability = d.discover_probability
  } else if (d.type === 'influence') {
    r.influence = { ...d.influence }
    r.actor_condition = d.actor_condition.trim()
    r.pair_conditions = d.pair_conditions.map(pair => ({ ...pair }))
  }
  return r
}

export function RulesTab() {
  const { t } = useI18n()
  const { toast } = useToast()
  const [rules, setRules] = useState<Rule[] | null>(null)
  const [draft, setDraft] = useState<DraftRule | null>(null)
  const [locations, setLocations] = useState<LocationRef[]>([])
  const [skills, setSkills] = useState<{ id: string; name: string }[]>([])
  const [quantities, setQuantities] = useState<Quantity[]>([])
  const [characters, setCharacters] = useState<CharacterRef[]>([])
  const [operationError, setOperationError] = useState('')

  const reload = useCallback(async () => {
    try {
      const data = await apiGet<{ rules?: Rule[] }>('/rules')
      setRules(data.rules || [])
    } catch (e) {
      toast(t('Failed to load') + ': ' + (e as Error).message, 'error')
    }
  }, [t, toast])

  useEffect(() => {
    reload()
  }, [reload])

  useEffect(() => {
    apiGet<Quantity[]>('/rules/quantities').then(setQuantities).catch(() => setQuantities([]))
    apiGet<{ id: string; name: string }[]>('/rules/skill-options').then(setSkills).catch(() => setSkills([]))
    loadLocations().then(setLocations).catch(() => setLocations([]))
    loadCharacters().then(setCharacters).catch(() => setCharacters([]))
  }, [])

  const sorted = useMemo(() => {
    if (!rules) return []
    return [...rules].sort((a, b) => (a.name || a.id || '').localeCompare(b.name || b.id || ''))
  }, [rules])

  const newRule = useCallback(() => {
    setOperationError('')
    setDraft({ ...EMPTY_DRAFT, influence: { ...EMPTY_DRAFT.influence }, pair_conditions: [], localized: {} })
  }, [])

  const editRule = useCallback((r: Rule) => {
    setOperationError('')
    setDraft(ruleToDraft(r))
  }, [])

  const copyRule = useCallback(() => {
    setDraft((prev) =>
      prev ? { ...prev, id: '', name: `${prev.name} (copy)`.trim(), origin: '', isNew: true } : prev,
    )
  }, [])

  const update = useCallback(<K extends keyof DraftRule>(key: K, value: DraftRule[K]) => {
    setDraft((prev) => (prev ? { ...prev, [key]: value } : prev))
  }, [])

  const save = useCallback(async () => {
    setOperationError('')
    if (!draft) return
    if (!draft.name.trim() || !draft.type) {
      toast(t('Name and type are required'), 'error')
      return
    }
    if (draft.type === 'influence' && (!Number.isFinite(draft.influence.factor) || draft.influence.factor < 0.1 || draft.influence.factor > 5)) {
      const message = t('Influence factor must be a finite number from 0.1 to 5.')
      setOperationError(message)
      toast(message, 'error')
      return
    }
    const ruleBody = draftToRule(draft)
    const target = draft.target_storage
    try {
      if (draft.type === 'influence') {
        const diagnostics = await apiPost<InfluenceValidation>('/rules/influence-validate', { rule: ruleBody })
        if (diagnostics.errors.length) {
          throw new Error(diagnostics.errors.map(issue => `${issue.path}: ${t(issue.message)}`).join('; '))
        }
      }
      let saved: Rule | undefined
      if (draft.isNew || !draft.id) {
        const r = await apiPost<{ rule?: Rule }>('/rules', { rule: ruleBody, target })
        saved = r.rule
        toast(t('Rule created'))
      } else {
        const r = await apiPut<{ rule?: Rule }>(
          `/rules/${encodeURIComponent(draft.id)}`,
          { rule: ruleBody, target },
        )
        saved = r.rule
        toast(t('Rule saved'))
      }
      await reload()
      // Keep the detail panel open on the just-saved rule instead of
      // bouncing back to the empty placeholder.
      if (saved) setDraft(ruleToDraft(saved))
    } catch (e) {
      const message = e instanceof ApiError && typeof e.detail !== 'string' ? JSON.stringify(e.detail) || e.message : (e as Error).message
      setOperationError(message)
      toast(t('Error') + ': ' + message, 'error')
    }
  }, [draft, reload, t, toast])

  // Both deletions ask in-app: the click arms, the dialog at the end acts.
  // One state for the two questions — they cannot be open at the same time.
  const [pendingDelete, setPendingDelete] = useState<'' | 'override' | 'rule'>('')
  const deleteOverride = useCallback(() => {
    if (!draft || draft.isNew) return
    setPendingDelete('override')
  }, [draft])
  const doDeleteOverride = useCallback(async () => {
    setPendingDelete('')
    if (!draft || draft.isNew) return
    try {
      await apiDelete(`/rules/${encodeURIComponent(draft.id)}?target=world`)
      toast(t('World override removed'))
      await reload()
      setDraft(null)
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [draft, reload, t, toast])

  const deleteRule = useCallback(() => {
    if (!draft || draft.isNew) return
    setPendingDelete('rule')
  }, [draft])
  const doDeleteRule = useCallback(async () => {
    setPendingDelete('')
    if (!draft || draft.isNew) return
    try {
      await apiDelete(`/rules/${encodeURIComponent(draft.id)}`)
      toast(t('Deleted'))
      await reload()
      setDraft(null)
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [draft, reload, t, toast])

  const move = useCallback(
    async (target: 'world' | 'shared') => {
      if (!draft || draft.isNew) return
      setOperationError('')
      if (draft.type === 'influence' && (!Number.isFinite(draft.influence.factor) || draft.influence.factor < 0.1 || draft.influence.factor > 5)) {
        setOperationError(t('Influence factor must be a finite number from 0.1 to 5.'))
        return
      }
      const oldTarget = draft.origin === 'shared' ? 'shared' : 'world'
      const ruleBody = draftToRule({ ...draft, target_storage: target })
      let destinationSaved = false
      try {
        // Upsert the complete rule under the same ID before removing its source.
        await apiPost('/rules', { rule: ruleBody, target })
        destinationSaved = true
        // …then drop the old-storage entry so the move is exclusive. If the
        // old entry was a world override of a shared rule, deleting the
        // world copy lets the shared baseline take over (move-to-shared
        // case); going world→shared then deletes the world override; going
        // shared→world keeps shared as baseline + adds the world override.
        if (target === 'shared' && oldTarget !== 'shared') {
          await apiDelete(`/rules/${encodeURIComponent(draft.id)}?target=world`)
        }
        toast(target === 'shared' ? t('Moved to shared') : t('Moved to world'))
        await reload()
        setDraft(null)
      } catch (e) {
        const detail = e instanceof ApiError && typeof e.detail !== 'string' ? JSON.stringify(e.detail) || e.message : (e as Error).message
        const message = destinationSaved
          ? `${t('Target layer saved, but the source layer could not be removed. Both layers are retained.')}: ${detail}`
          : detail
        setOperationError(message)
        await reload()
        toast(t('Error') + ': ' + message, 'error')
      }
    },
    [draft, reload, t, toast],
  )

  if (rules === null) return <div className="ga-loading">{t('Loading…')}</div>

  return (
    <div className="ga-twocol">
      <ListPane id="rules" label={t('Rules')}>
        <ListHeader
          title={t('Rules')}
          onNew={newRule}
          onCopy={copyRule}
          copyDisabled={!draft || draft.isNew}
          extra={
            <ImportButton
              onImported={() => reload()}
            />
          }
        />
        <ul className="ga-list">
          {sorted.length === 0 ? (
            <li className="ga-list-empty">{t('No rules yet')}</li>
          ) : (
            sorted.map((r) => {
              const isActive = draft && !draft.isNew && draft.id === r.id
              return (
                <li key={r.id || r.name}>
                  <button
                    type="button"
                    className={`ga-list-row${isActive ? ' is-active' : ''}`}
                    onClick={() => editRule(r)}
                  >
                    <span className="ga-list-row-main">
                      <strong>{r.name || r.id}</strong>
                      <span className="ga-list-row-sub">— {r.type}</span>
                    </span>
                    <span className={`ga-source ga-source-${(r._origin || 'shared').replace(' ', '-')}`}>
                      {r._origin || 'shared'}
                    </span>
                  </button>
                </li>
              )
            })
          )}
        </ul>
      </ListPane>
      <section className="ga-twocol-right">
        {draft ? (
          <>
            <DetailToolbar
              title={draft.name || draft.id || t('New rule')}
              onSave={save}
              onCancel={() => setDraft(null)}
              onDelete={
                draft.isNew
                  ? undefined
                  : draft.origin === 'world override'
                    ? deleteOverride
                    : deleteRule
              }
              deleteLabel={
                draft.origin === 'world override' ? t('Remove override') : t('Delete')
              }
              onMove={draft.isNew ? undefined : move}
              storage={
                draft.origin === 'shared'
                  ? 'shared'
                  : draft.origin === 'world override'
                    ? 'world override'
                    : 'world'
              }
              extra={
                draft.isNew || !draft.id || draft.origin === 'shared' ? null : (
                  <>
                    <ExportButton
                      endpoint={`/rules/${encodeURIComponent(draft.id)}/export`}
                      filename={`${draft.id}.zip`}
                    />
                    <PublishButton
                      packType="rule"
                      entityId={draft.id}
                      defaultName={draft.name || draft.id}
                    />
                  </>
                )
              }
            />
            {operationError ? <p className="ga-hint" role="alert">{operationError}</p> : null}
            <RuleForm
              draft={draft}
              quantities={quantities}
              skills={skills}
              locations={locations}
              characters={characters}
              onUpdate={update}
            />
          </>
        ) : (
          <div className="ga-placeholder">{t('Click a rule or create a new one.')}</div>
        )}
      </section>

      <ConfirmDialog
        open={!!pendingDelete}
        title={pendingDelete === 'override' ? t('Remove world override') : t('Delete rule')}
        message={(pendingDelete === 'override'
          ? t('The world\u2019s own version of "{name}" is dropped; the shared rule stays in force.')
          : t('Rule "{name}" is deleted and stops applying to this world.')
        ).replace('{name}', draft ? draft.name || draft.id : '')}
        confirmLabel={pendingDelete === 'override' ? t('Remove') : t('Delete')}
        danger
        onConfirm={() => {
          if (pendingDelete === 'override') void doDeleteOverride()
          else void doDeleteRule()
        }}
        onClose={() => setPendingDelete('')}
      />
    </div>
  )
}

interface RuleFormProps {
  quantities: Quantity[]
  draft: DraftRule
  skills: { id: string; name: string }[]
  locations: LocationRef[]
  characters: CharacterRef[]
  onUpdate: <K extends keyof DraftRule>(key: K, value: DraftRule[K]) => void
}

function RuleForm({ draft, locations, characters, skills, quantities, onUpdate }: RuleFormProps) {
  const { t } = useI18n()
  const selectedLocation = locations.find((l) => l.id === draft.target_location)
  const rooms = selectedLocation?.rooms || []
  const influenceRule = useMemo(() => draftToRule(draft), [draft])

  return (
    <div className="ga-form">
      {draft.origin ? (
        <div
          className={`ga-source ga-source-${draft.origin.replace(' ', '-')}`}
          style={{ alignSelf: 'flex-start' }}
        >
          {draft.origin}
        </div>
      ) : null}

      <Field label={t('Name')}>
        <input
          className="ga-input"
          name="rule-name"
          aria-label={t('Name')}
          value={draft.name}
          placeholder={t('Rule name')}
          onChange={(e) => onUpdate('name', e.target.value)}
        />
      </Field>

      <div className="ga-form-row">
        <Field label={t('Type')}>
          <select
            className="ga-input"
            name="rule-type"
            aria-label={t('Type')}
            value={draft.type}
            onChange={(e) => onUpdate('type', e.target.value as RuleType)}
          >
            <option value="block">{t('Block')}</option>
            <option value="force">{t('Force')}</option>
            <option value="discover">{t('Discover')}</option>
            <option value="modify">{t('Modify')}</option>
            <option value="influence">{t('Influence')}</option>
          </select>
        </Field>
        {draft.type !== 'influence' ? <Field
          label={t('Character')}
          hint={t('Empty applies the rule to all characters.')}
        >
          <select
            className="ga-input"
            value={draft.character}
            onChange={(e) => onUpdate('character', e.target.value)}
          >
            <option value="">— {t('all characters')} —</option>
            {characters.map((c) => (
              <option key={c.name} value={c.name}>
                {c.display_name || c.name}
              </option>
            ))}
          </select>
        </Field> : null}
      </div>

      <Field
        label={t('Storage')}
        hint={t('Shared is global for all worlds. World is this world only and overrides shared by id.')}
      >
        <select
          className="ga-input"
          name="rule-storage"
          aria-label={t('Storage')}
          value={draft.target_storage}
          onChange={(e) => onUpdate('target_storage', e.target.value as 'world' | 'shared')}
        >
          <option value="world">{t('World-specific (this world only)')}</option>
          <option value="shared">{t('Shared (all worlds)')}</option>
        </select>
      </Field>
      {draft.type === 'influence' ? <InfluenceRuleFields
        influence={draft.influence}
        actorCondition={draft.actor_condition}
        pairConditions={draft.pair_conditions}
        characters={characters}
        rule={influenceRule}
        onInfluence={value => onUpdate('influence', value)}
        onActorCondition={value => onUpdate('actor_condition', value)}
        onPairConditions={value => onUpdate('pair_conditions', value)}
      /> : null}

      {draft.type === 'modify' ? (
        <div className="ga-form-row">
          <Field label={t('Modified quantity')} hint={t(quantities.find((q) => q.id === draft.modify_quantity)?.description || '')}>
            <select className="ga-input" value={draft.modify_quantity}
              onChange={(e) => onUpdate('modify_quantity', e.target.value)}>
              {!quantities.some((q) => q.id === draft.modify_quantity) && (
                <option value={draft.modify_quantity}>{draft.modify_quantity}</option>
              )}
              {quantities.map((q) => <option key={q.id} value={q.id}>{t(q.label)}</option>)}
            </select>
          </Field>
          <Field label={t('Factor')} hint={t('Matching rule factors multiply. Each factor ranges from 0.1 to 5.')}>
            <input className="ga-input" type="number" min={0.1} max={5} step={0.05}
              value={draft.modify_factor}
              onChange={(e) => onUpdate('modify_factor', Number(e.target.value))} />
          </Field>
        </div>
      ) : null}

      {draft.type === 'block' ? (
        <div className="ga-form-row" style={{ alignItems: 'flex-start' }}>
          <Field label={t('Target')}>
            <select
              className="ga-input"
              value={draft.target_scope}
              onChange={(e) => onUpdate('target_scope', e.target.value as TargetScope)}
            >
              <option value="location">{t('Place / Room')}</option>
              <option value="any_room">{t('Any room (anywhere)')}</option>
              <option value="skill">{t('Skill')}</option>
              <option value="danger_level">{t('Danger level')}</option>
            </select>
          </Field>
          {draft.target_scope !== 'skill' && <Field label={t('Action')}>
            <select
              className="ga-input"
              value={draft.target_action}
              onChange={(e) => onUpdate('target_action', e.target.value as 'enter' | 'leave')}
            >
              <option value="enter">{t('Enter')}</option>
              <option value="leave">{t('Leave')}</option>
            </select>
          </Field>}
        </div>
      ) : null}

      {draft.type === 'block' && draft.target_scope === 'skill' ? (
        <Field label={t('Skills')} hint={t('Select the skills this rule blocks. Use state:<id> to check an active state.')}>
          <select className="ga-input" multiple size={6} value={draft.target_skills}
            onChange={(e) => onUpdate('target_skills', Array.from(e.target.selectedOptions, (o) => o.value))}>
            {skills.map((skill) => <option key={skill.id} value={skill.id}>{skill.name}</option>)}
          </select>
        </Field>
      ) : null}

      {draft.type === 'block' && draft.target_scope === 'location' ? (
        <>
          <Field label={t('Place')}>
            <select
              className="ga-input"
              value={draft.target_location}
              onChange={(e) => onUpdate('target_location', e.target.value)}
            >
              <option value="">-- {t('select')} --</option>
              {locations.map((l) => (
                <option key={l.id} value={l.id}>
                  {l.name || l.id}
                </option>
              ))}
            </select>
          </Field>
          {rooms.length > 0 ? (
            <Field label={t('Rooms')} hint={t('Multi-select with Ctrl/Cmd. No selection means the whole location.')}>
              <select
                className="ga-input"
                multiple
                size={6}
                value={draft.target_rooms}
                onChange={(e) => {
                  const next = Array.from(e.target.selectedOptions, (o) => o.value)
                  onUpdate('target_rooms', next)
                }}
              >
                {/* The two RESERVED rooms (§ A13a/§ A13b) may be unnamed —
                    `roomLabel` names them the way the world editor does, so a
                    rule targets "Hallway", never a raw `__floor__0`. */}
                {rooms.map((r) => (
                  <option key={r.id} value={r.id}>
                    {roomLabel(r, t)}
                  </option>
                ))}
              </select>
            </Field>
          ) : null}
        </>
      ) : null}

      {draft.type === 'block' && draft.target_scope === 'danger_level' ? (
        <Field label={t('Minimum danger level')}>
          <input
            type="number"
            className="ga-input"
            min={1}
            max={5}
            style={{ width: 80 }}
            value={draft.target_min_danger}
            onChange={(e) => onUpdate('target_min_danger', parseInt(e.target.value, 10) || 0)}
          />
        </Field>
      ) : null}

      {draft.type === 'force' ? (
        <>
          <Field label={t('Forced action')}>
            <select
              className="ga-input"
              value={draft.force_go_to}
              onChange={(e) => onUpdate('force_go_to', e.target.value as 'stay' | 'home')}
            >
              <option value="stay">{t('Stay (in place)')}</option>
              <option value="home">{t('Home (sleep place)')}</option>
            </select>
          </Field>
          <Field label={t('Sleep')}
            hint={t('State flags are the authority: "Fall asleep" sets is_sleeping (goes off-map at the sleep place), "Wake up" clears it and returns the character to where they were. A day/night rule pair needs BOTH directions — a rule that only sends someone to sleep never brings them back.')}>
            <select
              className="ga-input"
              value={draft.force_sleep}
              onChange={(e) => onUpdate('force_sleep', e.target.value as '' | 'sleep' | 'wake')}
            >
              <option value="">-- {t('no change')} --</option>
              <option value="sleep">{t('Fall asleep')}</option>
              <option value="wake">{t('Wake up')}</option>
            </select>
          </Field>
        </>
      ) : null}

      {draft.type === 'discover' ? (
        <Field
          label={t('Discovery probability per tick')}
          hint={t(
            'Rolled per agent-loop tick. On success one random unknown place within discovery range (see Game settings) is discovered. Skill checks go through the condition.',
          )}
        >
          <input
            type="number"
            className="ga-input"
            min={0}
            max={1}
            step={0.01}
            value={draft.discover_probability}
            onChange={(e) => onUpdate('discover_probability', parseFloat(e.target.value) || 0)}
          />
        </Field>
      ) : null}

      <Field
        label={draft.type === 'influence' ? t('Recipient condition') : t('Condition')}
        help={draft.type === 'influence' ? 'influence_recipient_condition' : 'condition'}
        hint={draft.type === 'influence' ? t('Evaluated against the recipient. Empty means always; all role and pair conditions must match.') :
          <>
            <strong>{t('Always')}</strong> always (hard block) · {' '}
            <strong>{t('Status')}</strong> stamina&gt;N, courage&lt;N, stress&gt;N, lust&gt;N · {' '}
            <strong>{t('Time / presence')}</strong> alone, night, day · {' '}
            <strong>{t('Relationship')}</strong> relationship:Name&gt;N, romantic:Name&gt;N · {' '}
            <strong>{t('Mood')}</strong> mood:happy · {' '}
            <strong>{t('State')}</strong> condition:&lt;tag&gt; · {' '}
            <strong>{t('Activity')}</strong> current_activity:cooking · {' '}
            <strong>{t('Schedule')}</strong> schedule:sleeping, schedule:awake · {' '}
            <strong>{t('Inventory')}</strong> has_item:item_a1b2c3d4 · {' '}
            <strong>{t('Room')}</strong> room_has_item:holoprojector · {' '}
            <strong>{t('Combinators')}</strong> AND / OR / NOT
          </>
        }
      >
        <input
          className="ga-input"
          name="recipient-condition"
          aria-label={draft.type === 'influence' ? t('Recipient condition') : t('Condition')}
          autoComplete="off"
          spellCheck={false}
          value={draft.condition}
          onChange={(e) => onUpdate('condition', e.target.value)}
          placeholder={t('e.g. has_item:item_a1b2c3d4 OR courage>50')}
        />
      </Field>

      <Field label={t('Message')}>
        <input
          className="ga-input"
          name="rule-message"
          aria-label={t('Message')}
          value={draft.message}
          onChange={(e) => onUpdate('message', e.target.value)}
          placeholder={t('e.g. You collapse from exhaustion')}
        />
      </Field>
    </div>
  )
}
