import { useCallback, useEffect, useState } from 'react'
import { useI18n } from '../../i18n/I18nProvider'
import { apiGet } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { MindPanel } from '@anima/player-ui'
import { DecencyExemptToggle } from '../../components/DecencyExemptToggle'
import { clockSettings, formatDate, formatTime, sameZoneDay,
  useClockSettings } from '../../lib/clockFormat'
import { useStatHistory, useStatLabels } from '../characters/statHistoryData'

/**
 * Mind tab — debug any (non-avatar) character's inner state in the Game-Admin.
 * Left: a "behaviour" debug block (why is the character feeling/acting like this)
 * from GET /characters/{name}/debug-activity. Right: the full player MindPanel
 * (Today · Diary · Memories · Relationships · History) reused for the picked
 * character — its data endpoints are already per-character.
 */

interface DebugActivity {
  character: string
  current_feeling: string
  state_flags: Record<string, boolean>
  status_effects: Record<string, number>
  active_effects?: string[]
  active_conditions?: { name?: string; source?: string; source_character?: string; started_at?: string; duration_hours?: number; boosts?: { stat: string; amount: number }[] }[]
  last_thought_at: string
  last_warning?: { type: string; value: string; ts: string } | null
  reasons: string[]
  mood_recent: { timestamp?: string; mood?: string; source?: string }[]
  state_recent: { ts: string; type: string; value: string }[]
  thoughts_recent: { ts: string; game_ts?: string; game_label?: string; action: string }[]
  block_rules: {
    id: string; name: string; action: string; message: string
    condition?: string; condition_met?: boolean; blocking?: boolean
  }[]
  force_rule?: { rule_name?: string; rule_id?: string; go_to?: string } | null
}

// A SYSTEM stamp → short time of day in the configured world timezone and
// clock format; the date is added only when it is not today. Defensive.
function fmtTs(iso?: string): string {
  if (!iso) return ''
  const clock = clockSettings()
  const time = formatTime(iso, clock)
  if (!time) return iso
  if (sameZoneDay(iso, new Date(), clock)) return time
  return `${formatDate(iso, clock, { month: 'short', day: 'numeric' })} ${time}`
}

/** The clock part of a rendered world-calendar label ("Summer, day 17 · 14:23
 *  · Year 3" → "14:23"). The SERVER renders the label; this only picks the
 *  short form for the inline badge — no game stamp is ever parsed here. */
function fmtGameClock(gameLabel?: string): string {
  // The label arrives with its clock part already in the configured display
  // format (the 12h shapes carry an AM/PM suffix), so this only cuts it out —
  // no reformatting, no game-stamp parsing.
  const m = /\b(\d{1,2}:\d{2}(?::\d{2})?(?:\s?[AP]M)?)/.exec(gameLabel || '')
  return m ? m[1].trim() : ''
}

/** Status-value changes with their causes, newest first — the list behind the
 *  sparklines in the Character tab. Reloads with the tab's Refresh. */
function StatHistoryCard({ character, revision }: { character: string; revision: number }) {
  const { t } = useI18n()
  const label = useStatLabels(character)
  const { rows, loading, error, retry } = useStatHistory(character, String(revision), 50)
  return (
    <div className="ga-mind-card">
      <h4>{t('Status value history')}</h4>
      {loading ? (
        <div className="ga-mind-empty">{t('Loading…')}</div>
      ) : error ? (
        <div className="ga-mind-empty" role="alert">
          {t('Could not load stat history.')}{' '}
          <button type="button" className="ga-btn ga-btn-sm" onClick={retry}>{t('Retry')}</button>
        </div>
      ) : rows.length > 0 ? (
        <ul className="ga-mind-list">
          {rows.map((row) => (
            <li key={row.id}>
              <span className="ts">
                {fmtTs(row.ts)}
                {row.game_label ? (
                  <span title={`${t('Game time')}: ${row.game_label}`}>
                    {' · 🕰 '}{fmtGameClock(row.game_label) || row.game_label}
                  </span>
                ) : null}
              </span>
              {Object.entries(row.changes).map(([key, change]) => {
                const cause = row.cause?.[key]
                return <div key={key} style={{ marginTop: 4, overflowWrap: 'anywhere' }}>
                  <span>{label(key)} {change.old}→<b>{change.new}</b></span>
                  {cause ? <div style={{ fontSize: '0.9em', opacity: 0.8 }}>
                    {cause.actor ? <div>{t('Actor')}: {cause.actor}</div> : null}
                    {cause.capped_base_delta !== undefined ? <>
                      <div>{t('Base delta')}: {cause.base_delta}</div>
                      <div>{t('After base chat cap')}: {cause.capped_base_delta}</div>
                      <div>{t('After influence')}: {cause.capped_base_delta} × {cause.factor} = {cause.capped_delta}</div>
                    </> : <>
                      <div>{t('Base delta')}: {cause.base_delta} × {cause.factor} = {cause.modified_delta}</div>
                      <div>{t('After chat cap')}: {cause.capped_delta}</div>
                    </>}
                    <div>{t('Actual change')}: {change.new - change.old}</div>
                    {cause.capped_delta !== change.new - change.old ? <div>{t('Limited by the stat range.')}</div> : null}
                    {cause.rules?.length ? <ul>
                      {cause.rules.map(rule => <li key={rule.id}>{rule.name || rule.id} ({rule.id}) × {rule.factor}</li>)}
                    </ul> : null}
                  </div> : null}
                  <span style={{ opacity: 0.55 }}> · {t(row.stat_labels?.[key] ?? row.label)}</span>
                </div>
              })}
              {row.event_id ? <div style={{ fontSize: '0.8em', opacity: 0.6, overflowWrap: 'anywhere' }}>{t('Event ID')}: {row.event_id}</div> : null}
            </li>
          ))}
        </ul>
      ) : (
        <div className="ga-mind-empty">{t('No stat changes recorded.')}</div>
      )}
    </div>
  )
}

export function MindTab() {
  // Subscribe to the shared clock settings so the stamps above re-render
  // once the server-configured format and timezone arrive.
  useClockSettings()
  const { t } = useI18n()
  const { toast } = useToast()
  const [characters, setCharacters] = useState<string[]>([])
  const [selected, setSelected] = useState('')
  const [dbg, setDbg] = useState<DebugActivity | null>(null)
  const [loading, setLoading] = useState(false)
  const [revision, setRevision] = useState(0)

  useEffect(() => {
    apiGet<{ characters?: { name: string }[] }>('/characters/list')
      .then((d) => setCharacters((d.characters || []).map((c) => c.name)))
      .catch((e) => toast(t('Failed to load') + ': ' + (e as Error).message, 'error'))
  }, [t, toast])

  const loadDebug = useCallback(async (name: string) => {
    if (!name) { setDbg(null); return }
    setLoading(true)
    setRevision((n) => n + 1)
    try {
      setDbg(await apiGet<DebugActivity>(`/characters/${encodeURIComponent(name)}/debug-activity`))
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
      setDbg(null)
    } finally {
      setLoading(false)
    }
  }, [t, toast])

  useEffect(() => { loadDebug(selected) }, [selected, loadDebug])

  return (
    <div className="ga-mind-layout">
      <div className="ga-mind-bar">
        <select className="ga-input" value={selected} onChange={(e) => setSelected(e.target.value)}>
          <option value="">— {t('select a character')} —</option>
          {characters.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
        {selected ? (
          <button className="ga-btn ga-btn-sm" disabled={loading} onClick={() => loadDebug(selected)}>
            {t('Refresh')}
          </button>
        ) : null}
        {dbg?.last_thought_at ? (
          <span style={{ opacity: 0.6, fontSize: 12 }}>
            {t('Last thought')}: {fmtTs(dbg.last_thought_at)}
          </span>
        ) : null}
      </div>

      {!selected ? (
        <div className="ga-placeholder">{t('Select a character to inspect its mind and behaviour.')}</div>
      ) : (
        <div className="ga-mind-body">
          <div className="ga-mind-debug">
            {/* Why — aggregated reasoning */}
            <div className="ga-mind-card">
              <h4>{t('Why this behaviour?')}</h4>
              {dbg && dbg.reasons.length > 0 ? (
                <div className="ga-mind-reason">
                  {dbg.reasons.map((r, i) => {
                    const cls = /^(must leave|blocked)/i.test(r) ? 'tag warn'
                      : /^forced/i.test(r) ? 'tag force' : 'tag'
                    return <span key={i} className={cls}>{r}</span>
                  })}
                </div>
              ) : (
                <div className="ga-mind-empty">{loading ? t('Loading…') : t('Nothing notable.')}</div>
              )}
            </div>

            {/* State flags */}
            {selected ? (
              <div className="ga-mind-card">
                <h4>{t('State flags')}</h4>
                {dbg && Object.values(dbg.state_flags || {}).some(Boolean) ? (
                  <div className="ga-mind-reason" style={{ marginBottom: 8 }}>
                    {Object.entries(dbg.state_flags).filter(([, v]) => v)
                      .map(([k]) => <span key={k} className="tag">{k}</span>)}
                  </div>
                ) : null}
                <DecencyExemptToggle character={selected} />
              </div>
            ) : null}

            {/* Active rules */}
            {dbg && (dbg.block_rules.length > 0 || dbg.force_rule) ? (
              <div className="ga-mind-card">
                <h4>{t('Active rules')}</h4>
                <ul className="ga-mind-list">
                  {dbg.force_rule ? (
                    <li style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: 6 }}>
                      <span className="tag force">{t('force')}</span>
                      <span style={{ fontWeight: 500 }}>{dbg.force_rule.rule_name || dbg.force_rule.rule_id}</span>
                      {dbg.force_rule.go_to ? <span style={{ opacity: 0.6 }}>→ {dbg.force_rule.go_to}</span> : null}
                    </li>
                  ) : null}
                  {dbg.block_rules.map((b) => {
                    // Block semantics: a satisfied condition activates the rule.
                    // enter: active = no entry; leave: active = no exit.
                    const isLeave = b.action === 'leave'
                    const active = b.blocking ?? b.condition_met ?? false
                    const status = isLeave
                      ? (active ? t('confined now') : t('free to leave'))
                      : (active ? t('no access') : t('access'))
                    return (
                      <li key={b.id} style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: 6 }}>
                        <span className={isLeave ? 'tag warn' : 'tag'}>{b.action || 'block'}</span>
                        <span style={{ fontWeight: 500 }}>{b.name || b.id}</span>
                        <span className={active ? 'tag warn' : 'tag ok'} title={b.condition || undefined}>{status}</span>
                        {b.message ? <span style={{ flexBasis: '100%', opacity: 0.6 }}>{b.message}</span> : null}
                      </li>
                    )
                  })}
                </ul>
              </div>
            ) : null}

            {/* Active effects (prompt filters) and conditions included in
                the system prompt, with their remaining duration. */}
            {dbg && ((dbg.active_effects && dbg.active_effects.length > 0)
                     || (dbg.active_conditions && dbg.active_conditions.length > 0)) ? (
              <div className="ga-mind-card">
                <h4>{t('Active effects')}</h4>
                {dbg.active_conditions && dbg.active_conditions.length > 0 ? (
                  <div className="ga-mind-reason" style={{ marginBottom: 8 }}>
                    {dbg.active_conditions.map((c, i) => (
                      <span key={i} className="tag warn"
                        title={[c.source, c.source_character ? `${t('giver')}: ${c.source_character}` : '',
                                c.duration_hours ? `${c.duration_hours}h` : '',
                                c.started_at ? `${t('since')} ${fmtTs(c.started_at)}` : '',
                                ...(c.boosts || []).map(b => `${b.stat} ${b.amount >= 0 ? '+' : ''}${b.amount}`)].filter(Boolean).join(' · ')}>
                        {c.name || '?'}{c.source_character ? ` ← ${c.source_character}` : ''}{c.duration_hours ? ` (${c.duration_hours}h)` : ''}
                      </span>
                    ))}
                  </div>
                ) : null}
                {dbg.active_effects && dbg.active_effects.length > 0 ? (
                  <ul className="ga-mind-list">
                    {dbg.active_effects.map((e, i) => (
                      <li key={i} style={{ opacity: 0.85 }}>{e}</li>
                    ))}
                  </ul>
                ) : null}
              </div>
            ) : null}

            <StatHistoryCard character={selected} revision={revision} />

            {/* Recent thoughts */}
            <div className="ga-mind-card">
              <h4>{t('Recent thought turns')}</h4>
              {dbg && dbg.thoughts_recent.length > 0 ? (
                <ul className="ga-mind-list">
                  {dbg.thoughts_recent.map((th, i) => (
                    <li key={i}>
                      <span className="ts">
                        {fmtTs(th.ts)}
                        {th.game_label ? (
                          <span title={`${t('Game time')}: ${th.game_label}`}>
                            {' · 🕰 '}{fmtGameClock(th.game_label) || th.game_label}
                          </span>
                        ) : null}
                      </span>
                      {th.action}
                    </li>
                  ))}
                </ul>
              ) : (
                <div className="ga-mind-empty">{t('No recent thought turns recorded (resets on restart).')}</div>
              )}
            </div>

            {/* Mood history */}
            <div className="ga-mind-card">
              <h4>{t('Mood history')}</h4>
              {dbg && dbg.mood_recent.length > 0 ? (
                <ul className="ga-mind-list">
                  {dbg.mood_recent.map((m, i) => (
                    <li key={i}>
                      <span className="ts">{fmtTs(m.timestamp)}</span>
                      {m.mood}{m.source ? <span style={{ opacity: 0.55 }}> · {m.source}</span> : null}
                    </li>
                  ))}
                </ul>
              ) : (
                <div className="ga-mind-empty">{t('No mood history.')}</div>
              )}
            </div>

            {/* State changes */}
            <div className="ga-mind-card">
              <h4>{t('Recent state changes')}</h4>
              {dbg && dbg.state_recent.length > 0 ? (
                <ul className="ga-mind-list">
                  {dbg.state_recent.map((s, i) => (
                    <li key={i}>
                      <span className="ts">{fmtTs(s.ts)}</span>
                      <span style={{ opacity: 0.6 }}>{s.type}: </span>{s.value}
                    </li>
                  ))}
                </ul>
              ) : (
                <div className="ga-mind-empty">{t('No state changes.')}</div>
              )}
            </div>
          </div>

          <div className="ga-mind-panel-wrap">
            <MindPanel character={selected} alwaysLabels withThoughts canDeleteEntries />
          </div>
        </div>
      )}
    </div>
  )
}
