import { StatRatesEditor } from './StatRatesEditor'
import { useCallback, useEffect, useState } from 'react'
import { useI18n } from '../../i18n/I18nProvider'
import { apiGet, apiPut } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { Field } from '@anima/player-ui'
import { ConfirmDialog } from '@anima/player-ui'
import { DetailToolbar } from '../../components/DetailToolbar'
import { type ItemRef } from '../../lib/refs'
import { GROUND_ROOM_ID, isFloorRoom, roomLabel, type Location, type Room, type FurnitureKitCatalog } from './worldTypes'
import { RoomItems } from './RoomItems'
import { BuildingModelPanel } from './BuildingModelPanel'
import { PromptChangedBadge } from './LocationEditor'

type Ambience = { daylight: number; tint: string | null }
type RoomDraft = Room & { ambience?: Ambience }

// ── Room editor ────────────────────────────────────────────────────────────

interface RoomEditorProps {
  location: Location
  room: Room
  items: ItemRef[]
  onChanged: () => void
  onDeleted: () => void
}

export function RoomEditor({ location, room, items, onChanged, onDeleted }: RoomEditorProps) {
  const { t } = useI18n()
  const { toast } = useToast()
  const [draft, setDraft] = useState<RoomDraft>(() => ({ ...room }))
  // Two tabs, mirroring the location editor: General (fields + items) and
  // 3D world (the room model). One draft spans both — Save persists it all.
  const [tab, setTab] = useState<'general' | '3d'>('general')

  useEffect(() => {
    setDraft({ ...room })
  }, [room])

  const [kitCatalog, setKitCatalog] = useState<FurnitureKitCatalog | null>(null)
  useEffect(() => {
    let stale = false
    setKitCatalog(null)
    apiGet<FurnitureKitCatalog>(`/world/furniture-kits?${new URLSearchParams({ location_id: location.id, room_id: room.id || '' })}`)
      .then((data) => { if (!stale) setKitCatalog(data) })
      .catch((e) => { if (!stale) toast(t('Error') + ': ' + (e as Error).message, 'error') })
    return () => { stale = true }
  }, [location.id, room.id, t, toast])

  const upd = useCallback(<K extends keyof RoomDraft>(k: K, v: RoomDraft[K]) => {
    setDraft((prev) => ({ ...prev, [k]: v }))
  }, [])

  const save = useCallback(async () => {
    try {
      const rooms = (location.rooms || []).map((r) => (r.id === room.id ? { ...r, ...draft } : r))
      await apiPut(`/world/locations/${encodeURIComponent(location.id)}`, { rooms })
      toast(t('Saved'))
      onChanged()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [draft, location, room.id, onChanged, t, toast])

  // The click arms the in-app question, the dialog at the end removes.
  const [confirmRemove, setConfirmRemove] = useState(false)
  const remove = useCallback(() => { setConfirmRemove(true) }, [])
  const doRemove = useCallback(async () => {
    setConfirmRemove(false)
    try {
      const rooms = (location.rooms || []).filter((r) => r.id !== room.id)
      await apiPut(`/world/locations/${encodeURIComponent(location.id)}`, { rooms })
      toast(t('Removed'))
      onDeleted()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [location, room, onDeleted, t, toast])

  // The ground is brought by the server and belongs to every location — the
  // author names it, but never creates or deletes it (plan-grundflaeche § 3).
  // The server puts it back anyway; offering the button would just lie. The
  // corridor of a storey (§ A13b) is the same kind of RESERVED room and is
  // treated identically everywhere below.
  const isGround = room.id === GROUND_ROOM_ID
  const isFloor = isFloorRoom(room.id)
  const isReserved = isGround || isFloor

  return (
    <>
      <DetailToolbar
        title={`${location.name} / ${roomLabel(room, t) || t('room')}`}
        onSave={save}
        onDelete={isReserved ? undefined : remove}
        deleteLabel={t('Remove room')}
      />
      <PromptChangedBadge
        locationId={location.id}
        roomId={room.id || ''}
        changed={room.prompt_changed}
        onCleared={onChanged}
      />
      {isGround ? (
        <p className="ga-form-hint" style={{ margin: '4px 8px 0' }}>
          {t('This is the ground of the location — the area no room takes up. Every location has one; it can be named, but not removed.')}
        </p>
      ) : isFloor ? (
        <p className="ga-form-hint" style={{ margin: '4px 8px 0' }}>
          {t('The corridor of a storey is brought by the server. Name it, describe it — it has no layout of its own.')}
        </p>
      ) : null}
      <nav className="ga-subtabs">
        {/* The yard has no diorama: its floor IS the terrain and its
            furnishing are props (contract § A13a), so the room 3D tab has
            nothing to offer there (user finding 2026-08-20). */}
        {([
          { id: 'general', label: 'General' },
          ...(isReserved ? [] : [{ id: '3d', label: '3D world' }]),
        ] as Array<{ id: 'general' | '3d'; label: string }>).map((tb) => (
          <button
            key={tb.id}
            type="button"
            className={`ga-btn ga-btn-sm${tab === tb.id ? ' ga-btn-primary' : ''}`}
            onClick={() => setTab(tb.id)}
          >
            {t(tb.label)}
          </button>
        ))}
      </nav>
      {tab === '3d' && !isReserved ? (
        <div className="ga-form">
          <BuildingModelPanel
            locationId={location.id}
            roomId={room.id || ''}
          />
        </div>
      ) : (
      <div className="ga-form">
        <div className="ga-form-row">
          <Field label={t('Room ID (read-only)')} hint={t('Permanent identifier — set when the room was created.')}>
            <input
              className="ga-input"
              value={draft.id || ''}
              readOnly
              disabled
              style={{ fontFamily: 'monospace', opacity: 0.7 }}
            />
          </Field>
          <Field label={t('Name')}>
            <input
              className="ga-input"
              value={draft.name || ''}
              onChange={(e) => upd('name', e.target.value)}
            />
          </Field>
        </div>
        {!isReserved && <Field label={t('Room type')}
          hint={t('Used by Furnish from kit. Auto guesses from the room name.')}>
          <select className="ga-input" disabled={!kitCatalog}
            value={kitCatalog?.room_types.some((type) => type.id === draft.room_type) ? draft.room_type : ''}
            onChange={(e) => upd('room_type', e.target.value)}>
            <option value="">{t('Auto ({guess})').replace('{guess}',
              kitCatalog?.room_types.find((type) => type.id === kitCatalog.room_type_guess)?.name || t('none'))}</option>
            {kitCatalog?.room_types.map((type) => <option key={type.id} value={type.id}>{type.name}</option>)}
          </select>
        </Field>}
        <section>
          <div className="ga-form-section-label">{t('Ambience')}</div>
          <div className="ga-form-row">
            <Field label={t('Daylight')}>
              <input type="range" min={0} max={100} step={1}
                aria-label={t('Daylight')}
                value={Math.round((draft.ambience?.daylight ?? 1) * 100)}
                onChange={(e) => upd('ambience', { daylight: Number(e.target.value) / 100, tint: draft.ambience?.tint ?? null })} />
              <span>{Math.round((draft.ambience?.daylight ?? 1) * 100)} %</span>
            </Field>
            <Field label={t('Tint')}>
              <input type="color" aria-label={t('Tint')} value={draft.ambience?.tint || '#ffffff'}
                disabled={!draft.ambience?.tint}
                onChange={(e) => upd('ambience', { daylight: draft.ambience?.daylight ?? 1, tint: e.target.value })} />
              <label className="ga-form-check"><input type="checkbox" checked={!draft.ambience?.tint}
                onChange={(e) => upd('ambience', { daylight: draft.ambience?.daylight ?? 1, tint: e.target.checked ? null : '#ffffff' })} />
                <span>{t('No tint')}</span></label>
            </Field>
          </div>
          <button type="button" className="ga-btn ga-btn-sm" onClick={() => upd('ambience', undefined)}>{t('Reset')}</button>
        </section>
        <StatRatesEditor value={draft.stat_rates || []} onChange={rates => upd('stat_rates', rates)} />
        <Field label={t('Description')}>
          <textarea
            className="ga-textarea"
            rows={2}
            value={draft.description || ''}
            onChange={(e) => upd('description', e.target.value)}
          />
        </Field>
        <div className="ga-form-row">
          <Field label={t('Decency')} hint={t('Overrides the location decency for this room. Empty = inherit.')}>
            <select
              className="ga-input"
              value={draft.decency || ''}
              onChange={(e) => upd('decency', (e.target.value || '') as Room['decency'])}
            >
              <option value="">{t('— inherit from location —')}</option>
              <option value="public">public</option>
              <option value="private">private</option>
              <option value="nude_ok">nude_ok</option>
            </select>
          </Field>
          <Field label={t('Style hint')} hint={t('Soft suggestion for the LLM (no code effect).')}>
            <input
              className="ga-input"
              list="style-hint-options"
              value={draft.style_hint || ''}
              onChange={(e) => upd('style_hint', e.target.value)}
            />
          </Field>
        </div>
        <div className="ga-form-row">
          <Field label={t('Indoor/Outdoor')} hint={t('Overrides the location for this room (e.g. a pool room in an indoor house = outdoor). Empty = inherit location.')}>
            <select className="ga-input" value={draft.indoor || ''}
              onChange={(e) => upd('indoor', e.target.value)}>
              <option value="">{t('Inherit from location')}</option>
              <option value="indoor">{t('Indoor')}</option>
              <option value="outdoor">{t('Outdoor')}</option>
            </select>
          </Field>
          <Field label={t('Swim allowed')}>
            <label className="ga-form-check">
              <input
                type="checkbox"
                checked={!!draft.swim_allowed}
                onChange={(e) => upd('swim_allowed', e.target.checked)}
              />
              <span>{t('Allow swimwear when wet')}</span>
            </label>
          </Field>
          <Field label={t('Activity hint')} hint={t('Free-text: what people usually do in this room.')}>
            <textarea
              className="ga-textarea"
              rows={2}
              value={draft.activity_hint || ''}
              onChange={(e) => upd('activity_hint', e.target.value)}
            />
          </Field>
        </div>

        <div>
          <div className="ga-form-section-label">{t('Image prompts')}</div>
          <div className="ga-form">
            <Field
              label={t('Day prompt')}
              help="image_prompt"
              hint={t('Per-room override. Falls back to the location day prompt when empty.')}
            >
              <textarea
                className="ga-textarea"
                rows={2}
                value={draft.image_prompt_day || ''}
                onChange={(e) => upd('image_prompt_day', e.target.value)}
              />
            </Field>
            <Field
              label={t('Night prompt')}
              help="image_prompt"
              hint={t('Per-room override. Falls back to the location night prompt when empty.')}
            >
              <textarea
                className="ga-textarea"
                rows={2}
                value={draft.image_prompt_night || ''}
                onChange={(e) => upd('image_prompt_night', e.target.value)}
              />
            </Field>
            {/* No diorama for the yard and none for a corridor — no
                source-image prompt either. */}
            {isReserved ? null : (
              <Field
                label={t('3D model prompt')}
                help="image_prompt"
                hint={t('Subject for the 3D-model source image (🧊). Falls back to the room description when empty.')}
              >
                <textarea
                  className="ga-textarea"
                  rows={2}
                  value={draft.image_prompt_building || ''}
                  onChange={(e) => upd('image_prompt_building', e.target.value)}
                />
              </Field>
            )}
          </div>
        </div>

        <RoomItems locationId={location.id} roomId={room.id || ''} items={items} />
      </div>
      )}

      <ConfirmDialog
        open={confirmRemove}
        title={t('Remove room')}
        message={t('Room "{name}" is removed from this location, with everything placed in it.')
          .replace('{name}', room.name || room.id || '')}
        confirmLabel={t('Remove')}
        danger
        onConfirm={() => { void doRemove() }}
        onClose={() => setConfirmRemove(false)}
      />
    </>
  )
}
